import {debugPanel,debugTraceOptions,debugTraceView} from './purchase-debug.mjs';

const DEMO=window.FP_DEMO===true;
const $=s=>document.querySelector(s);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={
 overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 strategies:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="16" cy="17" r="3" fill="currentColor" stroke="none"/>',
 marketplace:'<path d="m12 3 9 5-9 5-9-5zM3 8v10l9 5 9-5V8M12 13v10"/>',
 history:'<path d="M5 4h14v17l-3-2-4 2-4-2-3 2zM8 8h8M8 12h8M8 16h4"/>',
 reports:'<path d="M4 20h17M6 16v-5M12 16V4M18 16V8"/>',
 activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',
 settings:'<path d="m10 3 4 0 1 3 3 1 2 3-2 2 0 4-3 1-1 3-4 0-1-3-3-1-2-3 2-2 0-4 3-1z"/><circle cx="12" cy="12" r="3"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5M18 5a8 8 0 0 0-13 5m14 4A8 8 0 0 1 6 19"/>',
 arrow:'<path d="M5 18 19 4M7 4h12v12"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 12 8-12 8z"/>',
 edit:'<path d="m15 5 4 4M4 20l4-1L20 7l-4-4L4 15z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<path d="M3 5h17v15H3zM3 5V3h14M16 10h6v5h-6z"/>',
 check:'<path d="m5 12 4 4L19 6"/>',logout:'<path d="M9 4H4v16h5m5-13 5 5-5 5M9 12h11"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 6v1"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'
};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.overview}</svg>`;
const coin=c=>`<span class="coin-icon ${e(c.toLowerCase())}">${({BTC:'₿',BCH:'Ƀ',ZEC:'Z',LTC:'Ł',DOGE:'Ð',KAS:'K',RVN:'R'})[c]||e(c[0])}</span>`;
const btc=(n,d=5)=>(Number(n||0)/SAT).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const exact=n=>decimal(n||0);
const ago=s=>{if(!s)return 'Not synced';const n=Math.max(0,Math.floor((Date.now()-Date.parse(s))/60000));return n<1?'Just now':n<60?n+'m ago':n<1440?Math.floor(n/60)+'h ago':Math.floor(n/1440)+'d ago';};
const date=(s,full=false)=>new Date(s).toLocaleString('en-GB',{timeZone:state?.settings?.timezone||'Europe/Sofia',day:'2-digit',month:'short',...(full?{year:'numeric',hour:'2-digit',minute:'2-digit'}:{})});
const status=s=>`<span class="tag ${s==='COMPLETED'?'gray':s==='ACTIVE'?'':s==='UNKNOWN'||s==='FAILED'?'red':'amber'}">${s==='ACTIVE'?'<i class="status-dot"></i>':''}${e(s.replaceAll('_',' ').toLowerCase().replace(/^./,x=>x.toUpperCase()))}</span>`;
let ledgerMarket='BTC';
let api,state,page=(location.hash.slice(1)||'overview'),range=30,chartMetric='net',packageFilter='all',search='',historyFilter='all',modalFocus,dailyPage=0;
let toastTimer;
let savedAddresses=[];
const fiat=(value,currency)=>value===null||!Number.isFinite(value)?'—':new Intl.NumberFormat('en-US',{style:'currency',currency,minimumFractionDigits:2,maximumFractionDigits:2}).format(value);
const fiatBtc=(amount,currency)=>fiat(fiatValue(amount,ledgerMarket,currency,state.runtime.exchangeRates),currency);
const fiatCoin=(amount,coin,currency)=>fiat(fiatValue(amount,coin,currency,state.runtime.exchangeRates),currency);
const fiatPair=amount=>`${fiatBtc(amount,'USD')} · ${fiatBtc(amount,'EUR')}`;
const coinFiatPair=(amount,coin)=>`${fiatCoin(amount,coin,'USD')} · ${fiatCoin(amount,coin,'EUR')}`;
function rewardEstimateView(estimate){
  if(!estimate)return '';
  const team=estimate.scope==='team-member',known=Number.isFinite(estimate.fraction);
  return `<section class="reward-estimate"><h3>${team?'Your team share':'Per-block reward estimate'}</h3>${team?`<div class="budget-row"><span>My package share</span><b>${estimate.memberShares!==null&&estimate.totalShares!==null?e(estimate.memberShares)+' / '+e(estimate.totalShares)+' shares':known?'Based on committed '+ledgerMarket:'Unavailable'}</b></div><div class="budget-row"><span>My share of the team</span><b>${known?(estimate.fraction*100).toFixed(4)+'%':'Unknown'}</b></div>${estimate.totalAmount!==null?`<div class="budget-row"><span>Total team committed</span><b>${exact(estimate.totalAmount)} ${ledgerMarket}</b></div>`:''}${estimate.memberAmount!==null?`<div class="budget-row"><span>My commitment</span><b>${exact(estimate.memberAmount)} ${ledgerMarket}</b></div>`:''}`:''}${estimate.blocks.map(b=>`<div class="reward-estimate-coin"><div class="budget-row"><span>${team?'Whole team block reference':'Block reference'} · ${e(b.coin)}</span><b>${exact(b.fullAmount)} ${e(b.coin)}</b></div><div class="budget-row"><span>${team?'My estimated reward per block':'My estimated block reward'}</span><div class="amount-stack"><b>${b.amount===null?'Unavailable':exact(b.amount)+' '+e(b.coin)}</b>${b.amount!==null?'<small>'+coinFiatPair(b.amount,b.coin)+'</small>':''}</div></div></div>`).join('')}<p>${e(estimate.note||'Indicative amounts if a block is found; fees and the final payout can differ. These estimates do not count as earned or pending rewards. Live P&L uses NiceHash’s actual net member payout.')}${team?' Team participation can change while the lobby remains open.':''}</p></section>`;
}
function ratesNote(){const r=state.runtime.exchangeRates;return `<span class="rates-note ${ratesStale(r)?'negative':''}">${DEMO?'Illustrative rates':r?'NiceHash spot estimates':'Rates unavailable'}${r?' · '+e(date(r.at,true)):''}${ratesStale(r)?' · refresh needed':''}${state.runtime.ratesError?' · '+e(state.runtime.ratesError):''}</span>`;}
async function loadAddresses(){if(!DEMO&&!state.connection.configured)return [];try{savedAddresses=(await request('/api/payout-addresses')).addresses;return savedAddresses;}catch(err){toast('Saved payout addresses could not load: '+err.message,true);return [];}}
function addressField(name,label,currency,value=''){
  const addresses=savedAddresses.filter(a=>a.currency===currency);
  return `<div class="field full"><label for="${name}">${e(label)} · ${e(currency)}</label>${addresses.length?`<select class="saved-address" data-address-choice="${name}" aria-label="Saved ${e(currency)} payout addresses"><option value="">Choose a saved NiceHash address…</option>${addresses.map(a=>`<option value="${e(a.address)}">${e(a.name||a.currency)} · ${e(a.address)}</option>`).join('')}</select>`:''}<input id="${name}" name="${name}" value="${e(value)}" maxlength="200" autocomplete="off" placeholder="Paste an address, or leave blank for NiceHash default"><small>Choose a saved address or paste an address on the ${e(currency)} network. Blank uses NiceHash’s default/claim behavior. Saved NiceHash addresses support background strategies. An unsaved destination requires NiceHash 2FA for a manual purchase.</small></div>`;
}
function bindAddressChoices(){document.querySelectorAll('[data-address-choice]').forEach(el=>el.addEventListener('change',()=>{if(el.value)document.getElementById(el.dataset.addressChoice).value=el.value;}));}
function coinRewards(){const rows=rewardSummary(state.orders,state.rewards,{market:ledgerMarket,mode:state.settings.mode,from:fromTime(),to:Date.now()},state.runtime.exchangeRates);return `<section class="card ledger coin-rewards"><div class="card-head"><div><h2>Rewards by coin</h2><p>Personal coin quantities from the selected payment ledger and their current estimated value. Pending rewards stay separate.</p></div><button class="btn small" data-action="refresh-rates">${icon('refresh')}Refresh rates</button></div><div class="table-wrap"><table><thead><tr><th>Reward coin</th><th>Confirmed</th><th>Pending</th><th>Confirmed · USD</th><th>Confirmed · EUR</th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="table-package">${coin(r.coin)}<strong>${e(r.coin)}</strong></div></td><td class="mono">${exact(r.confirmed)}</td><td class="mono">${exact(r.pending)}</td><td class="mono">${fiat(r.usd,'USD')}</td><td class="mono">${fiat(r.eur,'EUR')}</td></tr>`).join('')}</tbody></table></div><div class="table-foot">${ratesNote()}<span>Display conversion only · no coins are exchanged</span></div></section>`;}

function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',4500);}
const liveRequest=createHttpClient({onAuthRequired:()=>{state=null;auth(false);}});
async function request(path,method='GET',body){
  return DEMO?api.request(path,method,body):liveRequest(path,method,body);
}
async function refresh(){state=await request('/api/state');render();}
async function action(path,method='POST',body={},success='Saved'){try{const result=await request(path,method,body);await refresh();toast(typeof success==='function'?success(result):success);return true;}catch(err){if(err.code==='NICEHASH_API_ERROR')try{await refresh();}catch{}toast(err.message,true);return false;}}
const fromTime=()=>reportingPeriod(range,state.settings.timezone).from;
const report=()=>totals(state.orders,state.rewards,{mode:state.settings.mode,market:ledgerMarket,from:fromTime(),to:Date.now()});
const ledgerRewards=()=>ledgerProjection(state.orders,state.rewards,ledgerMarket).rewards;
const ledgerStrategies=()=>state.strategies.filter(s=>paymentMarket(s)===ledgerMarket);
const activeOrders=()=>state.orders.filter(o=>isCurrent(o)&&o.mode===state.settings.mode&&paymentMarket(o)===ledgerMarket).map(orderView);
const totalRewards=o=>attributionHeld(o)?0:state.rewards.filter(r=>isRewardAccounted(r)&&r.orderId===o.id&&r.confirmed&&Number.isSafeInteger(rewardMarketValue(r,paymentMarket(o)))).reduce((n,r)=>n+rewardMarketValue(r,paymentMarket(o)),0);
function header(title,sub,actions=''){return `<div class="page-header"><div><div class="overline">THE MINING DESK</div><h1>${title}</h1><p>${sub}</p></div><div class="header-actions">${actions}</div></div>`;}
const newButton=()=>`<button class="btn primary" data-action="new-strategy">${icon('plus')} New strategy</button>`;
const exportButton=()=>`<button class="btn export" data-action="export-csv">${icon('download')} Export</button>`;
const dailyReport=(days=range)=>dailyProfits(state.orders,state.rewards,{mode:state.settings.mode,timezone:state.settings.timezone,market:ledgerMarket,days,rates:state.runtime.exchangeRates});
const dayLabel=day=>new Date(day+'T12:00:00Z').toLocaleDateString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric'});
const dayStats=(report,day)=>report.rows.find(r=>r.date===day)||{spend:0,earned:0,net:0,pending:0,unpriced:0,pendingUnpriced:0};
const profitClass=value=>value<0?'negative':value>0?'positive':'';
function dailyOverview(){
  const d=dailyReport(7),today=dayStats(d,d.toDate),yesterday=dayStats(d,shiftDate(d.toDate,-1));
  return `<section class="card daily-overview"><div class="card-head"><div><h2>Today’s net P&L</h2><p>${e(state.settings.timezone)} · day in progress</p></div></div><div class="daily-overview-body"><strong class="${profitClass(today.net)}">${exact(today.net)} <small>${ledgerMarket}</small></strong><p>${fiatPair(today.net)}</p><div class="budget-row"><span>Confirmed rewards</span><b>${exact(today.earned)} ${ledgerMarket}</b></div><div class="budget-row"><span>Net package spend</span><b>${exact(today.spend)} ${ledgerMarket}</b></div><div class="budget-row"><span>Yesterday’s net</span><b class="${profitClass(yesterday.net)}">${exact(yesterday.net)} ${ledgerMarket}</b></div>${today.unpriced?'<p class="negative">'+today.unpriced+' confirmed reward(s) await '+ledgerMarket+' valuation.</p>':''}<button class="link-btn" data-page="reports">Daily profit history →</button></div></section>`;
}
function dailyProfitView(){
  const d=dailyReport(),today=dayStats(d,d.toDate),yesterday=dayStats(d,shiftDate(d.toDate,-1));
  const size=14,pages=Math.ceil(d.rows.length/size);dailyPage=Math.min(dailyPage,pages-1);
  const rows=[...d.rows].reverse().slice(dailyPage*size,(dailyPage+1)*size);
  const money=(value,kind='')=>`<td class="mono ${kind}">${exact(value)}</td>`;
  return `<section class="card daily-profits" aria-labelledby="daily-profit-title"><div class="card-head"><div><h2 id="daily-profit-title">Daily profit & loss</h2><p>Calendar days in ${e(d.timezone)}. Confirmed reward value − net package spend.</p></div><button class="btn small" data-action="export-daily">${icon('download')}Export daily CSV</button></div><div class="daily-summary">${[['Today · in progress',today],['Yesterday',yesterday],['Selected period',d.total]].map(([label,r])=>`<article><span>${label}</span><strong class="${profitClass(r.net)}">${exact(r.net)} <small>${ledgerMarket}</small></strong><p>${fiatPair(r.net)}</p><small>Spend ${exact(r.spend)} · Rewards ${exact(r.earned)} ${ledgerMarket}</small>${r.unpriced?'<small class="negative">'+r.unpriced+' confirmed reward(s) unpriced</small>':''}</article>`).join('')}</div><div class="table-wrap"><table><caption class="sr-only">Daily ${ledgerMarket} ledger and current USD and EUR net estimates</caption><thead><tr><th>Day</th><th>Purchases</th><th>Net spend · ${ledgerMarket}</th><th>Confirmed · ${ledgerMarket}</th><th>Net P&L · ${ledgerMarket}</th><th>Net · USD</th><th>Net · EUR</th><th>Pending · ${ledgerMarket}</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${dayLabel(r.date)}</strong>${r.date===d.toDate?'<small>Today · in progress</small>':''}</td><td>${r.purchases}</td>${money(r.spend)}<td class="mono">${exact(r.earned)}${r.unpriced?'<small class="negative">'+r.unpriced+' unpriced</small>':''}</td>${money(r.net,profitClass(r.net))}<td class="mono ${profitClass(r.net)}">${fiat(r.usd,'USD')}</td><td class="mono ${profitClass(r.net)}">${fiat(r.eur,'EUR')}</td><td class="mono">${exact(r.pending)}${r.pendingUnpriced?'<small>'+r.pendingUnpriced+' unpriced</small>':''}</td></tr>`).join('')}</tbody><tfoot><tr><th>Period total</th><td>${d.total.purchases}</td>${money(d.total.spend)}${money(d.total.earned)}${money(d.total.net,profitClass(d.total.net))}<td class="mono">${fiat(d.total.usd,'USD')}</td><td class="mono">${fiat(d.total.eur,'EUR')}</td>${money(d.total.pending)}</tr></tfoot></table></div><div class="table-foot"><span>${dayLabel(d.fromDate)} – ${dayLabel(d.toDate)} · ${d.rows.length} days${pages>1?' · page '+(dailyPage+1)+' / '+pages:''}</span><div class="daily-pagination"><button class="btn small" data-action="daily-newer" ${dailyPage===0?'disabled':''}>Newer days</button><button class="btn small" data-action="daily-older" ${dailyPage>=pages-1?'disabled':''}>Older days</button></div></div><div class="daily-method"><p>Purchases and later team additions count on their saved spend dates. Refunds reduce spend on their recorded adjustment date; older entries without an adjustment history use their purchase date. Fees and unresolved reservations are included. Purchases counts each accepted or unresolved team addition.</p><p>Rewards count when confirmation was first recorded, which may be the import date for older payouts. Legacy rewards without a confirmation time use their saved reward date. Pending rewards remain separate and can move to a later day when confirmed. USD/EUR use the latest ${ledgerMarket} rate, not historical sale prices.</p>${d.undated?'<p class="negative">'+d.undated+' ledger event(s) have no valid timestamp and cannot be assigned to a day. Review the source ledger.</p>':''}${ratesNote()}</div></section>`;
}
function nav(){const list=[['overview','Overview'],['strategies','Strategies'],['marketplace','Marketplace'],['history','Package history'],['reports','Reports'],['activity','Activity log']];return list.map(([k,t])=>`<button class="nav-item ${page===k?'active':''}" data-page="${k}">${icon(k)}${t}${k==='strategies'?'<span class="count">'+state.strategies.length+'</span>':''}</button>`).join('');}
function render(){
  if(!state)return;
  const names={overview:'Overview',strategies:'Strategies',marketplace:'Marketplace',history:'Package history',reports:'Reports',activity:'Activity log',settings:'Settings'};
  if(!names[page])page='overview';
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="icon-btn mobile-close" aria-label="Close navigation" data-action="menu">${icon('close')}</button><a class="brand" href="#overview"><span class="logo-mark">F<span>↗</span></span><span class="brand-name">FastPool<small>EASYMINING</small></span></a><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">${nav()}</nav><div class="sidebar-spacer"></div><div class="engine-box"><div class="eyebrow">${DEMO?'YOUR PRIVATE TEST DRIVE':'AUTOMATION ENGINE'}</div><p>${DEMO?'Explore the controls.<br>Every satoshi here is simulated.':state.settings.running?'Your strategies are running.<br>Spending limits are enforced.':'Your engine is paused.<br>Review settings, then start.'}</p><button data-action="${DEMO?'self-host':'toggle-engine'}">${DEMO?'Get the self-hosted app ↗':state.settings.running?'Pause engine':'Start engine'}</button></div><button class="nav-item ${page==='settings'?'active':''}" data-page="settings">${icon('settings')}Settings & connection</button><div class="sidebar-foot"><span class="avatar">FP</span><div><strong>${DEMO?'Demo workspace':'Your workspace'}</strong><small>${DEMO?'Browser-local paper mode':'Private · single administrator'}</small></div><button class="icon-btn" aria-label="${DEMO?'About this application':'Sign out'}" data-action="${DEMO?'about':'logout'}">${icon(DEMO?'info':'logout')}</button></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button>EasyMining <span>/</span><strong>${names[page]}</strong></div><div class="top-actions"><select class="btn small" id="ledger-market" aria-label="Payment market">${MARKETS.map(m=>`<option value="${m}" ${ledgerMarket===m?'selected':''} ${m==='USDT'&&!DEMO&&!state.paymentMarkets?.includes('USDT')?'disabled':''}>${m} ledger</option>`).join('')}</select><span class="last-sync"><i class="status-dot" style="background:${state.settings.running?'#8caa69':'#b4baab'}"></i><span data-engine-label>${syncPresentation(state).engine}</span></span><span class="tag ${state.settings.mode==='live'?'red':'amber'}">${state.settings.mode==='live'?'LIVE BUYING':'PAPER MODE'}</span><button class="icon-btn" data-action="toggle-engine" aria-label="${state.settings.running?'Pause':'Start'} engine">${icon(state.settings.running?'pause':'play')}</button></div></header><main class="main">${({overview:overview,strategies:strategiesPage,marketplace:marketplace,history:history,reports:reports,activity:activity,settings:settings})[page]()}<footer class="app-footer"><span>FastPool EasyMining <span class="mono">v${DEMO?VERSION:e(state.version||VERSION)}</span> · ${DEMO?'Go edition preview':'Go server'}</span><span>${DEMO?'Illustrative data · preview runs in this browser':ledgerMarket+' ledger · '+e(state.settings.timezone)} · ${state.settings.mode==='paper'?'No real funds used':'Live funds enabled'}</span></footer></main></div></div>`;
  bindForms();
}
function demoNotice(){return DEMO?`<div class="notice"><span><strong>Paper workspace.</strong> This is an interactive preview with an illustrative ledger. Try manual purchases, strategies, and limits without spending funds.</span><a href="#" data-action="self-host">Run on your server ↗</a></div>`:'';}
function warnings(){return `<div data-sync-warnings>${warningContent()}</div>`;}
function warningContent(){
  let html='';const presentation=syncPresentation(state);
  if(ledgerMarket==='USDT'&&!marketLimits(state.settings,'USDT').dailyCap)html+=`<div class="callout warning">Set USDT spending limits before buying. <button class="link-btn" data-page="settings">Configure USDT limits →</button></div>`;
  const held=activeOrders().filter(attributionHeld);
  if(held.length)html+=`<div class="callout warning"><strong>Financial report is incomplete.</strong> ${held.length} imported purchase(s) are being checked for personal ownership. Their costs and rewards are excluded from P&L, coin totals and financial CSV until verified. Original amounts remain reserved by buying limits. Account sync repairs linked team records automatically. <button class="link-btn" data-action="sync">Check ownership now</button></div>`;
  if(presentation.unresolved.length)html+=`<div class="callout warning">${presentation.unresolved.length} purchase response(s) are still unverified. New purchases wait while account sync checks for a matching order. <button class="link-btn" data-page="history">View purchase details →</button></div>`;
  if(presentation.checking.length&&state.runtime.historyComplete!==false)html+=`<div class="callout">Checking ${presentation.checking.length} NiceHash purchase(s). ${presentation.automatic?'Account sync retries automatically.':'Use Sync now to check again.'} Existing costs remain reserved. <button class="link-btn" data-action="sync">Sync now</button></div>`;
  if(!DEMO&&state.version&&state.version!==VERSION)html+=`<div class="callout warning">The browser UI is v${VERSION}, but the running server reports v${e(state.version)}. Restart the updated application and reload this page.</div>`;
  if(state.runtime.lastError)html+=`<div class="callout warning">${state.runtime.lastErrorDetails?.method==='POST'?'Last purchase':'Connection'}: ${e(state.runtime.lastError)}${state.runtime.lastErrorDetails?.requestId?'<br>Request reference: '+e(state.runtime.lastErrorDetails.requestId):''}${state.runtime.lastErrorDetails?.path?.includes('/hashpower/shared/ticket/')?'<p>'+e(rejectionExplanation(state.runtime.lastErrorDetails.teamCheck))+'</p><button class="link-btn" data-action="purchase-diagnostics">Download purchase diagnostics</button>':''}</div>`;
  html+=historySyncPanel(state);
  html+=syncIssuesPanel(state);
  if(state.connection.serverConfigError)html+=`<div class="callout warning">Server configuration: ${e(state.connection.serverConfigError)}</div>`;
  if(state.runtime.ignoredUsdt)html+=`<div class="callout">BTC report excludes ${state.runtime.ignoredUsdt} USDT-priced account entries. This is informational and does not block BTC buying.</div>`;
  return html;
}
function overview(){
  const t=report();
  return header('EasyMining overview','A clear view of every package, strategy, and satoshi.',exportButton()+newButton())+demoNotice()+warnings()+
    `<div class="metrics"><article class="metric"><div class="metric-label">Net P&L ${icon('arrow')}</div><div class="metric-value ${t.net<0?'negative':'positive'}">${t.net>0?'+':''}${btc(t.net)}<small>${ledgerMarket}</small></div><div class="fiat-sub">${fiatPair(t.net)}</div><div class="metric-foot"><span class="${t.net<0?'negative':'positive'}">${t.roi===null?'—':t.roi.toFixed(1)+'%'}</span> return on package spend</div></article><article class="metric"><div class="metric-label">Total spent ${icon('wallet')}</div><div class="metric-value">${btc(t.spend)}<small>${ledgerMarket}</small></div><div class="fiat-sub">${fiatPair(t.spend)}</div><div class="metric-foot">${t.count} packages & team entries</div></article><article class="metric"><div class="metric-label">Confirmed rewards ${icon('check')}</div><div class="metric-value">${btc(t.earned)}<small>${ledgerMarket}</small></div><div class="fiat-sub">${fiatPair(t.earned)}</div><div class="metric-foot">${btc(t.pending)} ${ledgerMarket} awaiting confirmation</div></article><article class="metric"><div class="metric-label">Package hit rate ${icon('strategies')}</div><div class="metric-value">${t.winRate===null?'—':t.winRate.toFixed(1)}<small>${t.winRate===null?'':'%'}</small></div><div class="metric-foot">${t.wins} rewarded / ${t.settled} completed</div></article></div>
    <div class="rates-bar">${ratesNote()}<button class="link-btn" data-page="reports">Rewards by coin →</button></div><div class="dashboard-grid"><div><section class="card"><div class="card-head"><div><h2>Performance over time</h2><p>${ledgerMarket} equivalent · ${range?range+' days':'all records'}</p></div><select id="range" class="btn small" aria-label="Reporting period">${[[7,'Last 7 days'],[30,'Last 30 days'],[90,'Last 90 days'],[0,'All time']].map(([v,t])=>`<option value="${v}" ${range===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="chart-legend">${[['net','Net P&L'],['spend','Spending'],['earned','Rewards']].map(([k,n])=>`<button class="link-btn" style="${chartMetric===k?'color:#415d2e;font-weight:600':''}" data-chart="${k}"><i class="legend-dot ${k==='spend'?'gold':k==='earned'?'red':''}"></i>${n}</button>`).join('')}</div>${chart()}<div class="chart-foot"><span>Pending rewards excluded from P&L.</span><button class="link-btn" data-action="accounting">How this is calculated ↗</button></div></section><section class="card"><div class="card-head"><div><h2>Strategy control</h2><p>${ledgerStrategies().filter(s=>s.enabled).length} enabled · ${ledgerStrategies().length} total</p></div><button class="link-btn" data-page="strategies">Manage strategies ↗</button></div><div class="strategies-list">${ledgerStrategies().slice(0,3).map(strategyRow).join('')||'<div class="empty">Create your first buying strategy.</div>'}</div></section></div><aside class="dashboard-aside">${dailyOverview()}${budget()}<section class="card"><div class="card-head"><h2>Engine activity</h2><button class="icon-btn" data-action="evaluate" aria-label="Evaluate strategies now">${icon('refresh')}</button></div><div class="activity-preview">${state.events.slice(0,4).map(ev=>`<div class="activity-item"><span class="activity-bullet ${e(ev.level)}"></span><div class="activity-text">${e(ev.message)}<small>${ago(ev.at)}</small></div></div>`).join('')||'<div class="empty">Your engine activity appears here.</div>'}<button class="link-btn" data-page="activity">Open activity log →</button></div></section></aside></div><section class="card ledger"><div class="card-head"><div><h2>Recent packages</h2><p>Every purchase, with its outcome.</p></div><button class="link-btn" data-page="history">View all packages ↗</button></div>${ledger(activeOrders().filter(o=>Date.parse(o.createdAt)>=fromTime()).slice(0,5))}<div class="table-foot"><span>${t.active} package(s) active or pending in this period</span><span>Amounts in ${ledgerMarket}</span></div></section>`;
}
function chart(){
  const orders=activeOrders().filter(isAccounted),ids=new Set(orders.map(o=>o.id));
  const rewards=ledgerRewards().filter(r=>isRewardAccounted(r)&&ids.has(r.orderId)&&r.confirmed&&Number.isSafeInteger(r.valueBtc));
  const spending=orders.filter(isFunded).flatMap(spendEntries);
  const allDates=[...spending.map(entry=>Date.parse(entry.at)),...rewards.map(r=>Date.parse(r.confirmedAt||r.createdAt))];
  const start=range===0?(allDates.length?Math.min(...allDates):Date.now()-7*86400000):fromTime();
  const end=Date.now(),steps=30,points=[];
  for(let i=0;i<=steps;i++){
    const time=start+(end-start)*i/steps;
    const spend=spending.filter(entry=>Date.parse(entry.at)>=start&&Date.parse(entry.at)<=time).reduce((n,entry)=>n+entry.amountBtc,0);
    const earned=rewards.filter(r=>Date.parse(r.confirmedAt||r.createdAt)>=start&&Date.parse(r.confirmedAt||r.createdAt)<=time).reduce((n,r)=>n+r.valueBtc,0);
    points.push({time,value:({net:earned-spend,spend,earned})[chartMetric]});
  }
  if(!allDates.length)return '<div class="chart-wrap"><div class="chart-empty">Your performance chart starts with your first package.</div></div>';
  const low=Math.min(0,...points.map(p=>p.value)),high=Math.max(0,...points.map(p=>p.value));
  const gap=(high-low)||10000,min=low-gap*.12,max=high+gap*.12;
  const y=v=>20+(max-v)/(max-min)*166,x=i=>63+i/steps*625;
  const path=points.map((p,i)=>(i?'L':'M')+x(i).toFixed(2)+','+y(p.value).toFixed(2)).join(' ');
  const fill=path+' L688,195 L63,195 Z';
  const ticks=Array.from({length:5},(_,i)=>max-(max-min)*i/4);
  return `<div class="chart-wrap"><div class="chart-tooltip" id="chart-tooltip"></div><svg id="performance-chart" viewBox="0 0 715 235" preserveAspectRatio="none" role="img" aria-label="${chartMetric==='net'?'Cumulative net P&L':chartMetric==='spend'?'Cumulative package spending':'Cumulative confirmed rewards'} over the selected period"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#a0b77e" stop-opacity=".2"/><stop offset="100%" stop-color="#c8d8b1" stop-opacity=".02"/></linearGradient></defs>${ticks.map(v=>`<line x1="63" x2="688" y1="${y(v)}" y2="${y(v)}" stroke="#edf1e7" stroke-dasharray="3 4"/><text x="49" y="${y(v)+3}" text-anchor="end" fill="#a2ad96" font-size="9" font-family="inherit">${(v/SAT).toFixed(4)}</text>`).join('')}<path d="${fill}" fill="url(#chart-fill)"/><line x1="63" x2="688" y1="${y(0)}" y2="${y(0)}" stroke="#c5d2b5" stroke-dasharray="3 4"/><path d="${path}" fill="none" stroke="#7d965f" stroke-width="2.2" stroke-linejoin="round"/>${points.filter((_,i)=>i%6===0).map(p=>{const i=points.indexOf(p);return `<text x="${x(i)}" y="222" text-anchor="middle" fill="#a2ad96" font-size="9" font-family="inherit">${e(date(new Date(p.time).toISOString()))}</text>`;}).join('')}${points.map((p,i)=>`<rect x="${x(i)-10}" y="15" width="21" height="180" fill="transparent" data-tip="${e(date(new Date(p.time).toISOString())+' · '+exact(p.value)+' '+ledgerMarket)}"/><circle cx="${x(i)}" cy="${y(p.value)}" r="${i===steps?4:0}" fill="#7d965f"/>`).join('')}</svg></div>`;
}
const progressPercent=p=>p.percent===null?'—':p.percent.toLocaleString('en-US',{maximumFractionDigits:1})+'%';
const progressAmount=(value,market)=>Number.isSafeInteger(value)?(value/SAT).toLocaleString('en-US',{minimumFractionDigits:market==='USDT'?2:5,maximumFractionDigits:8}):'—';
function progressBar(p,label){return `<div class="mini-progress" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" ${p.percent===null?'':'aria-valuenow="'+p.width+'"'} aria-valuetext="${progressPercent(p)} of target"><span style="width:${p.width}%"></span></div>`;}
function strategyRow(s){
  const p=strategyProgress(s,state.orders,state.settings.mode);
  return `<div class="strategy-row">${coin(s.coin)}<div class="strategy-info"><strong>${e(s.name)}</strong><small>${s.mode==='team'?(levelSummary(s)||'Team ≥ '+s.minTeamShares+' shares'):s.kind==='odds'?'Odds at least 1:'+s.maxOdds:'Every '+s.intervalMinutes+' min'} · ${e(s.packageName)}</small><small>${s.continuous?'Continuous buying · targets track progress':'Lifetime budget and purchase limits apply'}</small></div><div class="strategy-stats"><b>${progressAmount(p.budget.used,p.market)} / ${progressAmount(p.budget.target,p.market)}</b> ${e(p.market)}<small>${progressPercent(p.budget)} of budget target</small>${progressBar(p.budget,'Budget target progress')}<small>${p.purchases.used} / ${p.purchases.target??'—'} purchases · ${progressPercent(p.purchases)}</small></div><button class="switch ${s.enabled?'on':''}" role="switch" aria-checked="${s.enabled}" aria-label="Enable ${e(s.name)}" data-toggle="${e(s.id)}"></button><button class="icon-btn" data-edit="${e(s.id)}" aria-label="Edit ${e(s.name)}">${icon('edit')}</button></div>`;
}
function budget(){const today=localParts(Date.now(),state.settings.timezone).date,spent=activeOrders().filter(isFunded).flatMap(spendEntries).filter(entry=>localParts(entry.at,state.settings.timezone).date===today).reduce((n,entry)=>n+entry.amountBtc,0),cap=marketLimits(state.settings,ledgerMarket).dailyCap,pc=cap>0?Math.min(100,spent/cap*100):0,circ=2*Math.PI*64;return `<section class="card budget-card"><h2>Daily spending limit</h2><div class="sub">Your bankroll, your boundaries.</div><div class="donut-wrap"><svg viewBox="0 0 166 166" aria-hidden="true"><circle cx="83" cy="83" r="64" fill="none" stroke="#eff2e8" stroke-width="15"/><circle cx="83" cy="83" r="64" fill="none" stroke="#c1d795" stroke-width="15" stroke-dasharray="${circ*pc/100} ${circ}" stroke-linecap="round"/></svg><div class="donut-center"><strong>${pc.toFixed(0)}<span style="font-size:14px">%</span></strong><small>of daily limit used</small></div></div><div class="budget-row"><span><i class="legend-dot" style="background:#c1d795"></i>Spent / reserved today</span><b>${btc(spent,5)} ${ledgerMarket}</b></div><div class="budget-row"><span><i class="legend-dot" style="background:#e6ecd9"></i>Available to spend</span><b>${btc(Math.max(0,cap-spent),5)} ${ledgerMarket}</b></div><div class="budget-line"></div><div class="budget-row"><span>Daily cap</span><b>${btc(cap,4)} ${ledgerMarket}</b></div><div class="budget-note">${state.settings.running?'The engine stops buying when a cap is reached.':'Buying is paused. Your limits remain saved.'} <button class="link-btn" data-page="settings">Edit limits ↗</button></div></section>`;}
function ledger(orders){return `<div class="table-wrap"><table><thead><tr><th>Package</th><th>Purchased</th><th>Cost</th><th>Reward value</th><th>Status</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><div class="table-package">${coin(o.coin)}<div>${e(o.name)}<small>${attributionHeld(o)?'Ownership verification pending':o.kind==='team'?o.shares+' team share(s)':'Solo package'} · ${state.settings.mode==='paper'?'paper':e(o.externalId?.slice(0,8)||'unresolved')}</small></div></div></td><td>${date(o.createdAt)}</td><td class="mono">${btc(o.costBtc+(o.feeBtc||0),5)}</td><td class="mono ${totalRewards(o)>0?'positive':''}">${totalRewards(o)>0?'+'+btc(totalRewards(o),5):'—'}</td><td>${status(o.status)}</td><td><button class="icon-btn" data-order="${e(o.id)}" aria-label="Open ${e(o.name)} details">${icon('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No packages in this view.</div></td></tr>'}</tbody></table></div>`;}
function strategiesPage(){return header('Buying, on your terms.','Set the rules. Give every purchase a clear reason.',newButton())+demoNotice()+warnings()+`<div class="callout">${state.settings.running?'Engine ready':'Engine paused'} · All strategies respect global spending caps, wallet reserve, and the error circuit breaker. <button class="link-btn" data-action="evaluate">Evaluate now →</button></div><div class="full-grid">${ledgerStrategies().map(s=>{
  const p=strategyProgress(s,state.orders,state.settings.mode),q=pickQuote(state.packages,s,state.orders.filter(o=>o.mode===state.settings.mode),purchaseProfile(state.settings)),decision=state.runtime.decisions?.find(d=>d.id===s.id)?.reason||guard(state,s,q)||'Ready for next evaluation';
  return `<article class="card strategy-card"><div class="top">${coin(s.coin)}<button class="switch ${s.enabled?'on':''}" role="switch" aria-checked="${s.enabled}" aria-label="Enable ${e(s.name)}" data-toggle="${e(s.id)}"></button></div><h3>${e(s.name)}</h3><p>${e(s.packageName)} · ${s.mode==='team'?'Team mining':'Solo mining'}<br>${({interval:'Regular interval purchases',price:'Buy only below a price ceiling',odds:'Wait for your probability threshold',team:'Join when the team reaches your threshold'})[s.kind]}</p><div class="detail-row"><span>Price ceiling / purchase</span><b>${btc(s.maxPrice,5)} ${ledgerMarket}</b></div><div class="detail-row"><span>Budget spent</span><b>${progressAmount(p.budget.used,p.market)} / ${progressAmount(p.budget.target,p.market)} ${e(p.market)}</b></div>${progressBar(p.budget,'Budget target progress')}<div class="strategy-progress-caption">${progressPercent(p.budget)} of lifetime budget${s.continuous?' target':''}</div><div class="detail-row"><span>Purchases</span><b>${p.purchases.used} / ${p.purchases.target??'—'}</b></div>${progressBar(p.purchases,'Purchase target progress')}<div class="strategy-progress-caption">${progressPercent(p.purchases)} of purchase${s.continuous?' target':' limit'}</div><p class="strategy-target-note">${s.continuous?'Continuous buying · these targets track progress and do not stop buying.':'Limited buying · these targets stop new purchases when reached.'}</p><div class="detail-row"><span>Buying interval</span><b>${s.intervalMinutes} minutes</b></div>${levelSummary(s)?'<div class="level-summary">'+e(levelSummary(s))+' joined shares → additional buys</div>':''}<div class="rule-note">${e(decision)}</div>${s.mode==='team'&&s.packageId?'<button class="btn small" data-follow-team="'+e(s.id)+'">Follow current matching teams</button>':''}<div class="bottom"><span class="tag ${s.enabled?'':'gray'}">${s.enabled?'Enabled':'Paused'}</span><button class="link-btn" data-edit="${e(s.id)}">Edit strategy ↗</button></div></article>`;
}).join('')||'<div class="card empty">No strategies yet. Start with a small paper budget.</div>'}</div>`;}
function marketplace(){const packages=state.packages.filter(p=>paymentMarket(p)===ledgerMarket&&(packageFilter==='all'||(packageFilter==='team'?p.team:!p.team))&&(!search||(p.name+' '+p.coin).toLowerCase().includes(search.toLowerCase())));return header('Find your next package.','Buy a package or team shares now, or build a buying strategy.',`<button class="btn" data-action="${DEMO?'about':'refresh-catalogue'}">${icon('refresh')}${DEMO?'Catalogue info':'Refresh catalogue'}</button>`)+demoNotice()+warnings()+`<div class="catalogue-tabs"><div class="segmented">${[['all','All packages'],['solo','Solo'],['team','Team']].map(([k,n])=>`<button data-package-filter="${k}" class="${packageFilter===k?'selected':''}">${n}</button>`).join('')}</div><input type="search" class="search-box" id="package-search" aria-label="Search packages" placeholder="Search package or coin…" value="${e(search)}"></div><div class="full-grid">${packages.map(p=>`<article class="card package-card"><div style="display:flex;justify-content:space-between;align-items:center">${coin(p.coin)}<span class="tag ${p.available?'':'gray'}">${p.available?'Available':'Unavailable'}</span></div><h3>${e(p.name)}</h3><div style="font-size:10px;color:#9da990">${e(p.coin)} · ${p.team?'Team mining · per share':'Solo mining'}</div><div class="price">${btc(p.price,p.market==='BTC'?5:2)} <small>${e(p.market)}</small></div><div class="package-stat"><span>Duration</span><b>${p.duration/3600} hours</b></div><div class="package-stat"><span>${p.team?'Current team odds':'Estimated odds'}</span><b>1 : ${p.odds?.toLocaleString('en-US',{maximumFractionDigits:1})||'—'}</b></div>${p.team?`<div class="package-stat"><span>Team shares joined</span><b>${p.teamShares}</b></div>${p.availabilityReason?'<p class="callout warning">'+e(p.availabilityReason)+'</p>':''}`:`<div class="package-stat"><span>Potential block reward</span><b>${p.reward??'—'} ${e(p.coin)}</b></div>`}<div class="package-actions"><button class="btn primary" data-buy-package="${e(p.id)}" ${!MARKETS.includes(p.market)||!p.available?'disabled':''}>${icon('wallet')}${p.team?'Buy shares':'Buy package'}</button><button class="btn" data-package="${e(p.id)}" ${!MARKETS.includes(p.market)?'disabled':''}>${icon('plus')}Strategy</button></div></article>`).join('')||'<div class="empty">No matching packages.</div>'}</div><div class="callout" style="margin-top:22px">${DEMO?'This preview uses a public catalogue snapshot. Demo team participation and balances are illustrative.':'Manual purchases have a final review, refresh the price before submission, and respect your global buying limits. They work while the strategy engine is paused.'} BTC and USDT use separate wallets, limits and ledgers. NiceHash’s purchase endpoint does not accept a limit price, so the local ceiling cannot guarantee the final execution price.</div>`;}
function history(){let os=activeOrders().filter(o=>Date.parse(o.createdAt)>=fromTime());if(historyFilter!=='all')os=os.filter(o=>o.status===historyFilter);return header('Every package has a story.','A complete record of your purchases, outcomes, and pending exposure.',exportButton()+`<button class="btn primary" data-action="${DEMO?'evaluate':'sync'}">${icon('refresh')}${DEMO?'Evaluate paper rules':'Sync NiceHash'}</button>`)+demoNotice()+warnings()+`<div class="catalogue-tabs"><div class="segmented">${[['all','All'],['ACTIVE','Active'],['COMPLETED','Completed'],['UNKNOWN','Needs review']].map(([k,n])=>`<button class="${historyFilter===k?'selected':''}" data-history-filter="${k}">${n}</button>`).join('')}</div><select class="btn" id="range" aria-label="Reporting period">${[[7,'Last 7 days'],[30,'Last 30 days'],[90,'Last 90 days'],[0,'All time']].map(([v,t])=>`<option value="${v}" ${range===v?'selected':''}>${t}</option>`).join('')}</select></div><section class="card">${ledger(os)}<div class="table-foot"><span>${os.length} records</span><span>Current mode: ${e(state.settings.mode)}</span></div></section>`;}
function resultRows(){
  const strategyIds=new Set(state.strategies.map(s=>s.id));
  const groups=[...ledgerStrategies().map(s=>({name:s.name,orders:state.orders.filter(o=>o.strategyId===s.id)})),
    {name:'Manual purchases',orders:state.orders.filter(o=>!o.strategyId&&o.source?.startsWith('Manual'))},
    {name:'Imported / other purchases',orders:state.orders.filter(o=>!strategyIds.has(o.strategyId)&&!(o.source?.startsWith('Manual')&&!o.strategyId))}];
  return groups.map(g=>{const t=totals(g.orders,state.rewards,{mode:state.settings.mode,from:fromTime(),to:Date.now(),market:ledgerMarket});return `<tr><td>${e(g.name)}</td><td>${t.count}</td><td class="mono">${btc(t.spend,5)}</td><td class="mono">${btc(t.earned,5)}</td><td class="mono ${t.net<0?'negative':'positive'}">${btc(t.net,5)}</td></tr>`;}).join('');
}
function reports(){const t=report(),ids=new Set(activeOrders().filter(isAccounted).map(o=>o.id)),rewards=ledgerRewards().filter(r=>isRewardAccounted(r)&&ids.has(r.orderId)&&Date.parse(r.confirmedAt||r.createdAt)>=fromTime()&&Date.parse(r.confirmedAt||r.createdAt)<=Date.now());return header('Know where you stand.','Package costs, confirmed rewards, and the value still at risk.',exportButton()+`<button class="btn" data-action="accounting">${icon('info')}Accounting method</button>`)+demoNotice()+warnings()+`<div class="catalogue-tabs"><span class="tag">${ledgerMarket} equivalent · ${e(state.settings.mode)} ledger</span><select class="btn" id="range" aria-label="Reporting period">${[[7,'Last 7 days'],[30,'Last 30 days'],[90,'Last 90 days'],[0,'All time']].map(([v,n])=>`<option value="${v}" ${range===v?'selected':''}>${n}</option>`).join('')}</select></div>${dailyProfitView()}${coinRewards()}<div class="report-grid"><section class="card form-card"><h2>Profit & loss</h2><p>Attributed personal costs and payouts, with USD / EUR estimates at the latest ${ledgerMarket} spot rate.</p>${[['Package spend',t.spend],['Confirmed reward value',t.earned],['Net cashflow / P&L',t.net],['Settled package P&L',t.settledNet],['Active & pending exposure',t.exposure],['Pending reward value',t.pending]].map(([n,v])=>`<div class="budget-row"><span>${n}</span><div class="amount-stack"><b class="${v<0?'negative':''}">${exact(v)} ${ledgerMarket}</b><small>${fiatPair(v)}</small></div></div>`).join('')}<div class="budget-line"></div><div class="budget-row"><span>Return on spend</span><b>${t.roi===null?'—':t.roi.toFixed(2)+'%'}</b></div><div class="budget-row"><span>Rewards without ${ledgerMarket} valuation</span><b>${t.unpriced}</b></div><p>${ledgerMarket} accounting valuations are retained after confirmation. Fiat P&L translates that ${ledgerMarket} ledger at today’s rate; the coin table values original coin quantities at today’s coin rates. Neither is an executed exchange.</p></section><section class="card form-card"><h2>Rewards ledger</h2><p>Pending rewards never count toward net P&L. Orphaned and donated rewards are excluded; their source records remain in package details.</p>${rewards.map(r=>`<div class="reward-row"><div><strong>${btc(r.amount,8)} ${e(r.coin)}</strong><small>${date(r.confirmedAt||r.createdAt)} · ${e((ledgerMarket==='USDT'?r.usdtValuation:null)||r.valuation||'Reported by NiceHash')}</small></div><div style="text-align:right"><span class="tag ${r.confirmed?'':'amber'}">${r.confirmed?(r.manualConfirmed?'Manually confirmed':'Confirmed'):'Pending'}</span><small>${Number.isSafeInteger(r.valueBtc)?exact(r.valueBtc)+' '+ledgerMarket:'Unpriced'}</small><small>${coinFiatPair(r.amount,r.coin)}</small>${!r.confirmed&&!DEMO?`<button class="link-btn" data-confirm-reward="${e(r.id)}">Verify payout ↗</button>`:''}${!Number.isSafeInteger(r.valueBtc)&&!DEMO?`<button class="link-btn" data-value-reward="${e(r.id)}">Add valuation ↗</button>`:''}</div></div>`).join('')||'<div class="empty">No rewards in this period.</div>'}</section></div><section class="card ledger"><div class="card-head"><h2>Results by strategy & purchase source</h2></div><div class="table-wrap"><table><thead><tr><th>Strategy</th><th>Purchases</th><th>Spend ${ledgerMarket}</th><th>Rewards ${ledgerMarket}</th><th>Net ${ledgerMarket}</th></tr></thead><tbody>${resultRows()}</tbody></table></div></section>`;}
function activity(){return header('A transparent engine.','See what happened, what was skipped, and why.',`<button class="btn" data-action="api-audit" ${DEMO?'disabled':''}>Run API audit</button><button class="btn" data-action="purchase-diagnostics">${icon('download')}Purchase diagnostics</button><button class="btn primary" data-action="evaluate">${icon('refresh')}Evaluate now</button>`)+demoNotice()+warnings()+debugPanel(state.purchaseDebug,DEMO,state.settings.timezone)+`<section class="card form-card"><h2>Latest strategy decisions</h2><p>Last evaluation: ${state.runtime.lastTick?date(state.runtime.lastTick,true):'Not evaluated yet'}</p>${(state.runtime.decisions||[]).map(d=>`<div class="reward-row"><strong>${e(d.name)}</strong><span>${e(d.reason)}</span></div>`).join('')||'<div class="empty">Run an evaluation to inspect each strategy’s decision.</div>'}</section><section class="card"><div class="card-head"><h2>Activity log</h2><span class="tag gray">Latest ${state.events.length} events</span></div><div class="event-list">${state.events.map(ev=>`<div class="event-row"><span>${date(ev.at,true)}</span><span class="tag ${ev.level==='error'?'red':ev.level==='warning'?'amber':'gray'}">${e(ev.level)}</span><span>${e(ev.message)}</span></div>`).join('')||'<div class="empty">No events yet.</div>'}</div></section>`;}
const amountFields=[['dailyCap','Daily spending cap'],['weeklyCap','Weekly spending cap'],['monthlyCap','Monthly spending cap'],['maxOrder','Maximum per purchase'],['reserve','Minimum wallet reserve'],['stopLoss','Stop loss · net spend'],['takeProfit','Take profit · net result'],['paperBalance','Paper starting balance']];
const field=(name,label,value,{type='text',small='',required=true,min='',max='',step=''}={})=>`<div class="field"><label for="${e(name)}">${label}</label><input id="${e(name)}" name="${e(name)}" type="${type}" value="${e(value)}" ${required?'required':''} ${min!==''?'min="'+min+'"':''} ${max!==''?'max="'+max+'"':''} ${step?'step="'+step+'"':''}>${small?'<small>'+small+'</small>':''}</div>`;
function settings(){const s=marketLimits(state.settings,ledgerMarket);return header('Stay in control.','Connection, bankroll limits, and the rules that apply to every strategy.',`<button class="btn" data-action="export-json">${icon('download')}Backup</button>`)+demoNotice()+warnings()+`<div class="settings-layout"><div><form id="risk-form" class="card form-card"><h2>Bankroll & buying limits</h2><p>All amounts are in ${ledgerMarket}. Limits count accepted purchases and unresolved reservations. A 0 stop loss or take profit disables that rule.</p><div class="field-grid">${amountFields.map(([k,n])=>field(k,n+' · '+ledgerMarket,exact(s[k]),{type:'number',min:0,step:'0.00000001'})).join('')}${field('maxActive','Maximum concurrent packages',s.maxActive,{type:'number',min:1,max:100})}${field('maxErrors','API error threshold',s.maxErrors,{type:'number',min:1,max:100})}${field('pollSeconds','Strategy evaluation interval · seconds',s.pollSeconds,{type:'number',min:30,max:3600})}${field('accountSyncSeconds','Account sync interval · seconds',s.accountSyncSeconds||60,{type:'number',min:30,max:3600,small:'Reads balances and external purchases even when the engine is paused.'})}<div class="field full"><label class="check-field"><input name="autoSync" type="checkbox" ${s.autoSync!==false?'checked':''}>Automatically sync NiceHash account</label><small>Temporary history gaps retry automatically. Verified external purchases count toward your spending limits.</small></div>${field('feeBufferBps','Price / fee reserve · basis points',s.feeBufferBps,{type:'number',min:0,max:1000,small:'100 bps = 1%. Reserved before buying; released after exact cost is known.'})}${field('timezone','Timezone',s.timezone,{small:'IANA name, e.g. Europe/Sofia or UTC.'})}<div class="field"><label for="mode">Execution mode</label><select name="mode" id="mode"><option value="paper" ${s.mode==='paper'?'selected':''}>Paper · simulated funds</option><option value="live" ${s.mode==='live'?'selected':''} ${DEMO?'disabled':''}>Live · NiceHash account</option></select><small>Changing mode pauses the engine and requires re-arming live buying.</small></div>${field('startHour','Global buying window · from',s.startHour,{type:'time'})}${field('endHour','Global buying window · until',s.endHour,{type:'time'})}</div><div class="form-error" id="risk-error"></div><div class="form-footer"><small>Stop rules pause new purchases.</small><button class="btn primary" type="submit">Save limits</button></div></form>${telegramPanel(state.telegram,{demo:DEMO,timezone:state.settings.timezone})}<section class="card form-card"><h2>Configuration & backups</h2><p>Export settings for a compact configuration file, or export JSON with the ledger. Import accepts both formats, including older exports. Review settings and paused strategies before applying.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn" data-action="export-settings">Export settings</button><button class="btn" data-action="export-json">Export JSON + ledger</button><button class="btn primary" data-action="import-settings">Import settings</button>${DEMO?'<button class="btn danger" data-action="reset-demo">Reset demo</button>':'<button class="btn" data-action="password">Change password</button>'}</div><input class="file-input" type="file" accept=".json,application/json" id="import-file"></section></div><div><form id="connection-form" class="card form-card"><h2>NiceHash connection</h2><p>${DEMO?'This hosted preview does not accept API credentials. Download and run the application on your server to connect your account.':state.connection.source==='server'?'Credentials are read from the server environment/configuration. Secrets are never returned to the browser or included in exports.':'Credentials saved in the web UI are encrypted on this server. They are never returned to the browser or included in exports.'}</p><div class="callout ${state.connection.verified?'':'warning'}" data-connection-status>${DEMO?'Demo · no NiceHash account connected':e(syncPresentation(state).connectionText)}</div><p data-account-sync-status>${DEMO?'The hosted preview has no private account connection.':s.autoSync!==false?'Automatic account sync is enabled · every '+(s.accountSyncSeconds||60)+' seconds, including while the engine is paused.':'Automatic account sync is disabled. Running live strategies still verify the account before buying.'}</p><div class="field-grid"><div class="field full"><label for="baseUrl">NiceHash API base URL</label><select id="baseUrl" name="baseUrl" ${DEMO?'disabled':''}><option value="https://api2.nicehash.com" ${state.connection.baseUrl!=='https://api-test.nicehash.com'?'selected':''}>https://api2.nicehash.com</option><option value="https://api-test.nicehash.com" ${state.connection.baseUrl==='https://api-test.nicehash.com'?'selected':''}>https://api-test.nicehash.com</option></select><small>Credential source: ${e(state.connection.source==='server'?(state.connection.serverSource||'server configuration'):state.connection.configured?'encrypted web settings':'not configured')}.</small></div><div class="field full"><label for="orgId">Organization ID</label><input id="orgId" name="orgId" value="${e(state.connection.organizationId)}" placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx" ${DEMO?'disabled':'required'}></div><div class="field full"><label for="key">API key</label><input id="key" name="key" type="password" autocomplete="off" placeholder="${state.connection.configured?'Saved · leave blank to keep':'NiceHash API key'}" ${DEMO?'disabled':''}></div><div class="field full"><label for="secret">API secret</label><input id="secret" name="secret" type="password" autocomplete="new-password" placeholder="${state.connection.configured?'Saved · leave blank to keep':'NiceHash API secret'}" ${DEMO?'disabled':''}></div></div><p style="margin-top:17px;font-size:10px;line-height:1.8;color:#9aab87">Use the permissions needed to read balances, read EasyMining history, and buy packages. Withdrawal permissions are not needed. Choose saved NiceHash payout addresses or paste a destination when buying manually or configuring a strategy.</p><div class="form-error" id="connection-error"></div><div class="form-footer">${DEMO?'<button class="btn primary" type="button" data-action="self-host">Get the application ↗</button>':'<button class="btn" type="submit">Save connection</button><button class="btn primary" type="button" data-action="sync">Test & sync</button>'}</div>${!DEMO&&state.connection.serverAvailable?'<div style="margin-top:15px"><button class="btn" type="button" data-action="use-server-connection">Use server configuration</button></div>':''}${state.connection.configured?'<div style="margin-top:15px"><button class="link-btn" type="button" data-action="disconnect">Disconnect account</button></div>':''}</form>${requestProfilePanel(s,{demo:DEMO,supported:DEMO||Array.isArray(state.purchaseRequestProfiles),serverVersion:state.version})}<section class="card form-card"><h2>Engine controls</h2><p>${DEMO?'Preview evaluations run in your browser. The self-hosted Docker service runs while your browser is closed.':'The server evaluates strategies in the background, even with your browser closed. After a restart, review and start the engine again.'}</p><div class="budget-row"><span>Engine</span><b data-engine-label>${syncPresentation(state).engine}</b></div><div class="budget-row"><span>Live buying</span><b data-live-armed>${s.liveArmed?'Armed':'Disarmed'}</b></div><div class="budget-row"><span>Available ${s.mode==='paper'?'paper':'wallet'} balance</span><b>${btc(s.mode==='paper'?s.paperBalance-totals(state.orders,state.rewards,{mode:'paper',market:ledgerMarket}).spend+totals(state.orders,state.rewards,{mode:'paper',market:ledgerMarket}).earned:marketBalance(state.runtime,ledgerMarket),5)} ${ledgerMarket}</b></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:21px"><button class="btn ${s.running?'danger':'primary'}" data-action="toggle-engine">${icon(s.running?'pause':'play')}${s.running?'Pause engine':'Start engine'}</button><button class="btn" data-action="evaluate">Evaluate now</button>${!DEMO?'<button class="btn danger" data-action="arm">Arm live buying</button>':''}</div></section></div></div>`;}
function openModal(content,{wide=false}={}){
  modalFocus=document.activeElement;
  $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1">${content}</section></div>`;
  setTimeout(()=>$('.modal input:not([type="hidden"]),.modal select,.modal button')?.focus(),0);
}
function closeModal(){$('#modal-root').innerHTML='';modalFocus?.focus();}
const modalHead=(title,sub='')=>`<div class="modal-head"><div><h2 id="modal-title">${title}</h2>${sub?'<p>'+sub+'</p>':''}</div><button class="icon-btn" type="button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>`;
async function purchaseModal(packageId){
  const p=state.packages.find(p=>p.id===packageId);if(!p)return;
  await loadAddresses();
  openModal(modalHead(p.team?'Buy team shares':'Buy a package',e(p.name)+' · '+e(p.coin)+(p.mergeCoin?' + '+e(p.mergeCoin):'')+' rewards')+`<div class="callout ${state.settings.mode==='live'?'warning':''}">${state.settings.mode==='live'?'Live purchase · spends your NiceHash '+paymentMarket(p)+' balance.':'Paper purchase · simulated funds only.'} Manual buying respects your global caps, wallet reserve, and buying window. Your strategy engine can remain paused.</div><form id="purchase-form"><div class="field-grid">${p.team?field('shares','Number of team shares',1,{type:'number',min:1,max:100}):'<input type="hidden" name="shares" value="1">'}<div class="field full"><label>Catalogue price ${p.team?'per share':''}</label><strong>${exact(money(p,'costBtc'))} ${e(paymentMarket(p))}</strong><small>NiceHash will be refreshed for your purchase review.</small></div>${addressField('payoutAddress','Reward payout address',p.coin)}${p.mergeCoin?addressField('mergePayoutAddress','Merged reward payout address',p.mergeCoin):''}</div><div class="form-error" id="purchase-error"></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Review ${state.settings.mode==='live'?'live':'paper'} purchase →</button></div></form>`);
  bindAddressChoices();
  $('#purchase-form').addEventListener('submit',async ev=>{
    ev.preventDefault();const button=ev.submitter;if(button.disabled)return;button.disabled=true;
    try{const input=Object.fromEntries(new FormData(ev.target));input.shares=Number(input.shares);input.packageId=packageId;const quote=await request('/api/purchases/quote','POST',input);reviewPurchaseModal(quote);}
    catch(err){if($('#purchase-error'))$('#purchase-error').textContent=err.message;}
    finally{if(button.isConnected)button.disabled=false;}
  });
}
function reviewPurchaseModal(raw){
  const q=orderView(raw);
  openModal(modalHead('Review your '+(q.mode==='live'?'live':'paper')+' purchase',e(q.name)+' · '+(q.team?q.shares+' team share(s)':'1 solo package'))+`<div class="purchase-review"><div class="review-price">${exact(q.costBtc)} <small>${paymentMarket(q)}</small></div><p>Current package cost · ${fiatPair(q.costBtc)}</p><div class="budget-row"><span>Cost plus configured price / fee reserve</span><b>${exact(q.reservedBtc)} ${e(paymentMarket(q))}</b></div>${[['Payout address · '+q.coin,q.payoutAddress||'NiceHash default / claim'],...(q.mergeCoin?[['Payout address · '+q.mergeCoin,q.mergePayoutAddress||'NiceHash default / claim']]:[])].map(([label,address])=>`<div class="review-destination"><small>${e(label)}</small><strong>${e(address)}</strong></div>`).join('')}</div>${rewardEstimateView(q.rewardEstimate)}<p class="callout ${q.mode==='live'?'warning':''}">${q.mode==='live'?'Confirming submits one real purchase. Live buying must be armed in Settings.':'Confirming creates one simulated purchase.'} The review expires after two minutes. A higher refreshed price requires a new review. NiceHash does not offer a guaranteed execution price.</p>${q.requiresTwofa?field('purchase-twofa','Current NiceHash 2FA code','',{small:'Used once for this unsaved destination. Never stored.'}):''}<div class="form-error" id="purchase-error"></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn ${q.mode==='live'?'danger':'primary'}" id="confirm-purchase">${q.mode==='live'?'Confirm & buy with '+paymentMarket(q):'Confirm paper purchase'}</button></div>`);
  $('#confirm-purchase').addEventListener('click',async ev=>{
    const button=ev.currentTarget;if(button.disabled)return;button.disabled=true;button.textContent='Submitting purchase…';
    try{
      const result=await request('/api/purchases','POST',{quoteId:q.id,twofaToken:$('#purchase-twofa')?.value.trim()||''});closeModal();await refresh();orderModal(result.order.id);
      toast(result.order.status==='UNKNOWN'?'Response uncertain. Review this order in NiceHash before reconciling.':result.order.status==='FAILED'?'NiceHash rejected the purchase. Review its error.':result.replayed?'Existing purchase shown; no new order submitted.':q.mode==='paper'?'Paper purchase created':'Live purchase submitted',['UNKNOWN','FAILED'].includes(result.order.status));
    }catch(err){if($('#purchase-error'))$('#purchase-error').textContent=err.message;button.textContent='Check / submit this review';if(button.isConnected)button.disabled=false;}
  });
}
async function strategyModal(id,defaults={}){
  await loadAddresses();
  const old=state.strategies.find(s=>s.id===id),s={...STRATEGY_DEFAULTS,market:ledgerMarket,...(ledgerMarket==='USDT'?{coin:'BCH',packageName:'Silver 5',maxPrice:units('5'),budget:units('100')}:{}),...old,...defaults};
  openModal(modalHead(old?'Edit strategy':'Create a buying strategy','Repeat purchases within your chosen market and global spending limits.')+`<form id="strategy-form"><input type="hidden" name="id" value="${e(old?.id||'')}"><div class="field-grid"><div class="field full"><label for="strategy-name">Strategy name</label><input id="strategy-name" name="name" value="${e(s.name)}" required maxlength="120"></div><div class="field"><label for="kind">Buying rule</label><select name="kind" id="kind">${[['interval','Regular interval'],['price','Price ceiling'],['odds','Probability threshold'],['team','Team share threshold']].map(([k,n])=>`<option value="${k}" ${s.kind===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="strategy-mode">Package type</label><select id="strategy-mode" name="mode"><option value="solo" ${s.mode==='solo'?'selected':''}>Solo package</option><option value="team" ${s.mode==='team'?'selected':''}>Team share(s)</option></select></div><div class="field"><label for="strategyMarket">Payment market</label><select id="strategyMarket" name="market" ${old&&state.orders.some(o=>o.strategyId===old.id&&isFunded(o))?'disabled':''}>${MARKETS.map(m=>`<option value="${m}" ${paymentMarket(s)===m?'selected':''}>${m}</option>`).join('')}</select><small>Each strategy spends one currency. Create a separate strategy for another market.</small></div>${field('coin','Coin',s.coin,{small:'BTC, BCH, ZEC, LTC, or another catalogue coin. DOGE appears as a merged reward on LTC packages.'})}${field('packageName','Package name',s.packageName,{small:'Exact name from the catalogue, e.g. Gold S or Team Gold.'})}${field('maxPrice','Maximum per purchase · '+paymentMarket(s),exact(s.maxPrice),{type:'number',min:'0.00000001',step:'0.00000001',small:'Ceiling for each purchase or level addition. Price is checked before sending.'})}${field('budget','Lifetime strategy budget · '+paymentMarket(s),exact(s.budget),{type:'number',min:'0.00000001',step:'0.00000001',small:'Tracks lifetime spending in continuous mode. Enforced as a limit when continuous buying is off.'})}${field('intervalMinutes','Minimum interval · minutes',s.intervalMinutes,{type:'number',min:1,max:43200,small:'Applies between level additions too. The example uses 1 minute.'})}${field('maxPurchases','Maximum purchases',s.maxPurchases,{type:'number',min:1,max:100000,small:'Tracks purchase progress in continuous mode. Enforced as a limit when continuous buying is off.'})}${field('shares','Team shares per purchase',s.shares,{type:'number',min:1,max:100,small:'Used only for team packages.'})}${field('minTeamShares','Minimum existing team shares',s.minTeamShares,{type:'number',min:0,max:100000,small:'Applied to all team purchases.'})}<div class="field full team-level-editor" id="team-level-editor"></div>${field('maxOdds','Maximum odds denominator · 1 in N',s.maxOdds,{type:'number',min:1,max:1000000000,small:'Probability rule only. A smaller N is a higher chance.'})}${field('packageId','Optional fixed package / team ID',s.packageId,{required:false,small:'Leave empty to follow new matching lobbies. A fixed team ID stops matching after that lobby closes.'})}<div class="field full" id="strategy-addresses"></div>${field('startHour','Buying window · from',s.startHour,{type:'time'})}${field('endHour','Buying window · until',s.endHour,{type:'time'})}<div class="field full"><label>Buying days · ${e(state.settings.timezone)}</label><div class="days">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<button type="button" class="day ${s.days.includes(i)?'selected':''}" data-day="${i}" aria-pressed="${s.days.includes(i)}">${d}</button>`).join('')}</div></div><div class="field full"><label class="check-field"><input id="strategy-continuous" name="continuous" type="checkbox" ${s.continuous?'checked':''}>Keep buying until I pause this strategy</label><small>Continues after rewards and after your lifetime budget/purchase targets are reached. Targets remain editable and progress stays visible. Global spending caps, schedules, wallet reserve and reconciliation checks still apply.</small><label class="check-field"><input name="stopOnWin" type="checkbox" ${s.stopOnWin?'checked':''}>Stop this strategy after a confirmed reward</label><label class="check-field"><input name="enabled" type="checkbox" ${s.enabled?'checked':''}>Enable this strategy</label></div></div><div class="form-error" id="strategy-error"></div><div class="modal-actions" style="justify-content:space-between"><div>${old?'<button type="button" class="btn danger" id="delete-strategy">Delete</button>':''}</div><div style="display:flex;gap:8px"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save strategy</button></div></div></form>`,{wide:true});
  const readTeamLevels=bindTeamLevels($('#strategy-form'),s);
  const updateContinuous=()=>{const on=$('#strategy-continuous').checked;document.querySelector('[name="stopOnWin"]').disabled=on;};
  updateContinuous();$('#strategy-continuous').addEventListener('change',updateContinuous);

  const updatePayoutFields=()=>{const primary=$('#payoutAddress')?.value??s.payoutAddress??'',merge=$('#mergePayoutAddress')?.value??s.mergePayoutAddress??'',code=$('#coin').value.trim().toUpperCase(),p=state.packages.find(p=>paymentMarket(p)===$('#strategyMarket').value&&p.coin===code&&p.name.toLowerCase()===$('#packageName').value.trim().toLowerCase());$('#strategy-addresses').innerHTML=`<div class="field-grid">${addressField('payoutAddress','Reward payout address',code,primary)}${p?.mergeCoin?addressField('mergePayoutAddress','Merged reward payout address',p.mergeCoin,merge):''}</div>`;bindAddressChoices();};
  $('#strategyMarket').addEventListener('change',()=>{
    const market=$('#strategyMarket').value,p=state.packages.find(p=>paymentMarket(p)===market&&p.team===($('#strategy-mode').value==='team')&&p.available);
    if(p){$('#coin').value=p.coin;$('#packageName').value=p.name;$('#maxPrice').value=exact(money(p,'costBtc'));$('#budget').value=exact(money(p,'costBtc')*20);}
    document.querySelector('label[for="maxPrice"]').textContent='Maximum per purchase · '+market;
    document.querySelector('label[for="budget"]').textContent='Lifetime strategy budget · '+market;
    updatePayoutFields();
  });
  updatePayoutFields();$('#coin').addEventListener('change',updatePayoutFields);$('#packageName').addEventListener('change',updatePayoutFields);
  $('#strategy-form').addEventListener('submit',async ev=>{ev.preventDefault();const f=new FormData(ev.target),b=Object.fromEntries(f);for(const k of ['maxPrice','budget']){try{b[k]=$('#'+k).value===''?s[k]:units($('#'+k).value);}catch(err){$('#strategy-error').textContent=err.message;return;}}for(const k of ['intervalMinutes','shares','maxPurchases','minTeamShares','maxOdds'])b[k]=b[k]===undefined?s[k]:Number(b[k]);b.days=[...document.querySelectorAll('.day.selected')].map(x=>Number(x.dataset.day));b.market=$('#strategyMarket').value;b.continuous=f.has('continuous');b.enabled=f.has('enabled');b.stopOnWin=!b.continuous&&f.has('stopOnWin');b.mergePayoutAddress||='';b.coin=b.coin.toUpperCase();b.teamLevels=readTeamLevels();try{await request('/api/strategies','POST',b);closeModal();await refresh();toast('Strategy saved');}catch(err){$('#strategy-error').textContent=err.message;}});
  $('#delete-strategy')?.addEventListener('click',()=>{openModal(modalHead('Delete this strategy?')+`<p class="callout">${e(s.name)} will be removed. Existing purchases and rewards remain in your ledger.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn danger" id="confirm-delete">Delete strategy</button></div>`);$('#confirm-delete').addEventListener('click',async()=>{if(await action('/api/strategies/'+old.id,'DELETE',{},'Strategy deleted'))closeModal();});});
}
function orderModal(id){const raw=state.orders.find(o=>o.id===id);if(!raw)return;const o=orderView(raw);const rs=ledgerRewards().filter(r=>!r.supersededBy&&r.orderId===id);openModal(modalHead(e(o.name),'Package and accounting details')+`<div class="detail-grid">${[['Status',o.status],['Execution mode',o.mode],['Purchased',date(o.createdAt,true)],['Package type',attributionHeld(o)?'Awaiting ownership verification':o.kind],[isRejectedAttempt(o)?'Requested cost · rejected, not spent':attributionHeld(o)?'Unverified provider order amount':'Package cost',exact(o.costBtc)+' '+ledgerMarket],['Reserved fee / price buffer',exact(o.feeBtc||0)+' '+ledgerMarket],['Refund',exact(o.refundBtc||0)+' '+ledgerMarket],['NiceHash order ID',o.externalId||'Not available'],...(o.attemptedTeamId?[['Rejected team target',o.attemptedTeamId]]:[]),['Request ID',o.requestId||'Imported'],['Source',o.source],['Payout address · '+o.coin,o.payoutAddress||'NiceHash default / claim'],...(o.mergeCoin?[['Payout address · '+o.mergeCoin,o.mergePayoutAddress||'NiceHash default / claim']]:[])].map(([n,v])=>`<div><small>${n}</small>${e(v)}</div>`).join('')}</div>${o.teamBuys?.length?'<section class="reward-estimate"><h3>Team buying levels</h3><div class="table-wrap"><table><thead><tr><th>Joined shares ≥</th><th>Added shares</th><th>Additional '+ledgerMarket+'</th><th>Status</th></tr></thead><tbody>'+o.teamBuys.map(b=>'<tr><td>'+e(b.threshold)+'</td><td>'+e(b.shares)+'</td><td>'+exact(b.amountBtc)+'</td><td>'+e(b.status)+(b.error?'<small>'+e(b.error)+'</small>':'')+'</td></tr>').join('')+'</tbody></table></div><p>One team commitment and one reward allocation. Failed additions do not count as spend. Pending additions require account verification.</p></section>':''}${isRejectedAttempt(o)?'<p class="callout">NiceHash explicitly rejected this attempt. It is not treated as an owned team package or package spend. The same review will not submit again.</p>':''}${attributionHeld(o)?'<p class="callout warning"><strong>Excluded from financial totals.</strong> '+e(o.attribution.reason)+' Account sync will retry. Provider reward amounts below have not been attributed to you.</p>':''}${rewardEstimateView(o.rewardEstimate)}${o.rewardEstimateNote?'<p class="callout warning">'+e(o.rewardEstimateNote)+'</p>':''}${o.kind==='team'&&!o.rewardEstimate?'<p class="callout">Historical team share is unavailable. Sync NiceHash to read your contribution; no full-block estimate is assumed.</p>':''}${o.accountingNote?'<p class="callout" style="margin-top:22px">'+e(o.accountingNote)+'</p>':''}${o.error?'<p class="callout warning">'+e(o.error)+'</p>':''}${o.syncPending?'<p class="callout">Account sync is checking this purchase automatically. '+e(o.syncPending.reason)+'</p>':''}${o.rewardPrecisionNote?'<p class="callout">'+e(o.rewardPrecisionNote)+'</p>':''}<div style="margin-top:22px"><strong style="font-size:12px">${attributionHeld(o)?'Unattributed provider rewards · excluded':'Reported personal rewards'}</strong>${rs.map(r=>`<div class="reward-row"><span>${btc(r.amount,8)} ${e(r.coin)}<small>${e((ledgerMarket==='USDT'?r.usdtValuation:null)||r.valuation||'Reported by NiceHash')}</small></span><div>${status(!isRewardAccounted(r)?'EXCLUDED':r.confirmed?'COMPLETED':'PENDING')}<small>${Number.isSafeInteger(r.valueBtc)?exact(r.valueBtc)+' '+ledgerMarket:'No '+ledgerMarket+' valuation'}</small><small>${coinFiatPair(r.amount,r.coin)}</small></div></div>`).join('')||'<p style="font-size:11px;color:#96a48a">No rewards reported for this package.</p>'}</div><div class="modal-actions">${!DEMO&&['UNKNOWN','SUBMITTING'].includes(o.status)?`<button class="btn danger" id="reconcile-order">Reconcile purchase</button>`:''}<button class="btn primary" data-action="close-modal">Done</button></div>`);
  $('#reconcile-order')?.addEventListener('click',()=>reconcileModal(o));
}
function reconcileModal(o){openModal(modalHead('Reconcile this purchase','Check the NiceHash order history before resolving an uncertain charge.')+`<form id="reconcile-form"><div class="field-grid"><div class="field full">${field('externalId','Link the matching NiceHash order / team ID',o.pendingTeamPurchase?o.externalId:'',{required:false,small:'Provide the exact matching order. No purchase is retried.'})}</div><div class="field full">${field('confirm',o.pendingTeamPurchase?'Or type VERIFIED NO ADDITION':'Or type VERIFIED NO PURCHASE','',{required:false,small:o.pendingTeamPurchase?'Only if NiceHash confirms the last addition was not charged. Earlier team shares and spend remain recorded.':'Only if NiceHash confirms that no purchase or charge occurred.'})}</div><div class="field full">${field('password','Administrator password','',{type:'password',required:false})}</div><div class="field full">${field('note','Reconciliation note','',{required:false})}</div><div class="field full"><label for="reconcile-action">Resolution</label><select id="reconcile-action" name="action"><option value="link">Link order ID, or verify no purchase</option><option value="final-debit">Record verified final cost and refund</option></select></div>${field('costBtc',o.pendingTeamPurchase?'Total cost including earlier team purchases · '+paymentMarket(o):'Original cost · '+paymentMarket(o),exact(o.costBtc),{type:'number',min:0,step:'0.00000001',required:false})}${field('refundBtc','Verified refund · '+paymentMarket(o),exact(o.refundBtc||0),{type:'number',min:0,step:'0.00000001',required:false})}</div><div class="form-error" id="reconcile-error"></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn danger" type="submit">Save reconciliation</button></div></form>`);$('#reconcile-form').addEventListener('submit',async ev=>{ev.preventDefault();try{const b=Object.fromEntries(new FormData(ev.target));if(b.action==='final-debit'){b.costBtc=units(b.costBtc);b.refundBtc=units(b.refundBtc);if(paymentMarket(o)==='USDT'){b.costAmount=b.costBtc;b.refundAmount=b.refundBtc;delete b.costBtc;delete b.refundBtc;}b.externalId='';}await request('/api/reconcile','POST',{...b,id:o.id});closeModal();await refresh();toast('Purchase reconciled. Engine remains paused.');}catch(err){$('#reconcile-error').textContent=err.message;}});}
function confirmRewardModal(id){
  openModal(modalHead('Verify a received payout','Use only after checking the actual NiceHash payout or blockchain transaction.')+`<p class="callout warning">This records a manual accounting confirmation. It does not claim or withdraw a reward. Your evidence note is retained in the audit log.</p><form id="confirm-reward-form"><div class="field-grid"><div class="field full">${field('payout-password','Administrator password','',{type:'password'})}</div><div class="field full">${field('payout-note','Verified transaction ID or payout reference','')}</div></div><div class="form-error" id="payout-error"></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Record payout as received</button></div></form>`);
  $('#confirm-reward-form').addEventListener('submit',async ev=>{ev.preventDefault();try{await request('/api/reward-confirmation','POST',{id,password:$('#payout-password').value,note:$('#payout-note').value});closeModal();await refresh();toast('Payout confirmation recorded with your evidence note');}catch(err){$('#payout-error').textContent=err.message;}});
}
function accountingModal(){openModal(modalHead('How the numbers work',ledgerMarket+' ledger, with pending rewards kept separate.')+`<div class="callout">Net P&L = confirmed reward ${ledgerMarket} value − all funded package costs − reserved fees + refunds. Active package purchases are already included in spending.</div><ul class="helper-list"><li>Settled package P&L includes completed packages and their confirmed rewards.</li><li>ROI divides net P&L by funded package spend.</li><li>Hit rate divides rewarded completed entries by completed entries. A team is one package for hit rate and concurrency. Each accepted level addition counts toward the strategy purchase limit.</li><li>Imported orders awaiting ownership verification are excluded from financial reports; original provider amounts stay reserved by buying limits. Shared execution totals are retained only as superseded audit data after member attribution.</li><li>Team block reward estimates use your committed amount divided by the whole team’s committed amount. Live earnings use the member’s reported net reward, which is already allocated to you; it is never multiplied by that percentage again.</li><li>Non-BTC reward values come from NiceHash’s reported BTC equivalent or the account rate at confirmation. These are valuations, not actual sale proceeds.</li><li>USDT reward values use NiceHash’s BTC/USDT rate when first valued and remain fixed after confirmation. Missing rates leave rewards unpriced. Fiat figures use current spot estimates.</li><li>Unpriced rewards remain visible and are excluded from totals until valued.</li><li>Extra shares bought on NiceHash are recorded when their increased contribution is first observed. They count toward that day’s spending limits.</li><li>Uncertain purchases reserve their full cost. They block further purchases until reconciled.</li><li>Reports use calendar days in the configured timezone, purchase timestamps and first observed reward confirmations. Older payouts imported for the first time may appear on the import date. Use All time to compare full lifetime totals.</li><li>BTC and USDT purchases use separate spending limits and ledgers. No currency conversion is executed.</li><li>Spending limits reduce exposure; buying rules do not change the probability of finding a block.</li></ul><div class="modal-actions"><button class="btn primary" data-action="close-modal">Understood</button></div>`);}
function selfHost(){openModal(modalHead('Your own mining desk.','Run the full application on your server with Docker.')+`<p class="callout">This download includes the native Go server, web UI, background strategy engine, encrypted API settings, SQLite ledger, and tests. The hosted preview uses browser-local illustrative data.</p><ol class="helper-list"><li>Download and extract the release. For an upgrade, keep your original installation directory, .env and data volume.</li><li>Run <code>docker compose up -d --build</code>.</li><li>Open <code>http://localhost:8080</code>. For a remote server, use an SSH tunnel or your HTTPS reverse proxy.</li><li>For a new installation, find the setup token in <code>docker compose logs</code>. Existing installations retain their administrator password.</li><li>Test & sync the connection, review budgets, and test strategies in paper mode.</li><li>Arm live buying explicitly when ready. A funded purchase has not been verified, and changing languages does not establish a fix for NiceHash’s 404.</li></ol><div class="modal-actions"><button class="btn" data-action="close-modal">Close</button><a class="btn primary" href="/downloads/fastpool-easymining-v${VERSION}.zip" download>${icon('download')}Download Go release & Docker</a></div>`);}
function armModal(){openModal(modalHead('Enable real purchases','This allows the server to spend your configured NiceHash BTC and USDT balances under their separate limits.')+`<p class="callout warning">Review your package budgets and global spending caps. Arming does not start the engine. The next step is to start it explicitly.</p><form id="arm-form"><div class="field-grid"><div class="field full">${field('arm-password','Administrator password','',{type:'password'})}</div><div class="field full">${field('arm-confirm','Type ENABLE LIVE BUYING','')}</div></div><div class="form-error" id="arm-error"></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn danger" type="submit">Arm live buying</button></div></form>`);$('#arm-form').addEventListener('submit',async ev=>{ev.preventDefault();try{await request('/api/arm','POST',{password:$('#arm-password').value,confirm:$('#arm-confirm').value});closeModal();await refresh();toast('Live buying armed. Review strategies, then start the engine.');}catch(err){$('#arm-error').textContent=err.message;}});}
function bindForms(){
  $('#telegram-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const f=new FormData(ev.target),b=Object.fromEntries(f);for(const k of ['enabled','purchases','dailyReports'])b[k]=f.has(k);b.threadId=Number(b.threadId||0);const button=ev.submitter;if(button)button.disabled=true;try{await request('/api/telegram','POST',b);await refresh();toast('Telegram settings saved');}catch(err){$('#telegram-error').textContent=err.message;if(button)button.disabled=false;}});
  $('#ledger-market')?.addEventListener('change',ev=>{ledgerMarket=ev.target.value;dailyPage=0;render();});
  $('#range')?.addEventListener('change',ev=>{range=Number(ev.target.value);dailyPage=0;render();});
  $('#package-search')?.addEventListener('input',ev=>{search=ev.target.value;const pos=ev.target.selectionStart;render();$('#package-search')?.focus();$('#package-search')?.setSelectionRange(pos,pos);});
  $('#request-profile-form')?.addEventListener('submit',async ev=>{
    ev.preventDefault();const value=new FormData(ev.target).get('purchaseRequestProfile');if(!value)return;
    const changed=value!==purchaseProfile(state.settings);
    try{await request('/api/settings','POST',{purchaseRequestProfile:value});await refresh();toast(changed?'Purchase API format saved. Engine paused and live buying disarmed.':'Purchase API format unchanged.');}catch(error){$('#request-profile-error').textContent=error.message;}
  });
  $('#purchaseRequestProfile')?.addEventListener('change',ev=>{$('#request-profile-help').textContent=REQUEST_PROFILES.find(p=>p.id===ev.target.value)?.description||'';});
  $('#risk-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const b=Object.fromEntries(new FormData(ev.target));try{for(const [k] of amountFields)b[k]=units(b[k]);for(const k of ['maxActive','maxErrors','pollSeconds','accountSyncSeconds','feeBufferBps'])b[k]=Number(b[k]);b.autoSync=new FormData(ev.target).has('autoSync');if(ledgerMarket==='USDT'){b.usdtLimits=Object.fromEntries(amountFields.map(([k])=>[k,b[k]]));for(const [k] of amountFields)delete b[k];}await request('/api/settings','POST',b);await refresh();toast('Limits and settings saved');}catch(err){$('#risk-error').textContent=err.message;}});
  $('#connection-form')?.addEventListener('submit',async ev=>{ev.preventDefault();try{await request('/api/connection','POST',Object.fromEntries(new FormData(ev.target)));await refresh();toast('Credentials saved. Test & sync to verify.');}catch(err){$('#connection-error').textContent=err.message;}});
  $('#import-file')?.addEventListener('change',async ev=>{const f=ev.target.files[0];ev.target.value='';if(!f)return;try{if(f.size>20*1024*1024)throw new Error('Choose a JSON file smaller than 20 MB. Use Export settings for a compact configuration file.');let b;try{b=JSON.parse(await f.text());}catch{throw new Error('This file is not valid JSON. Choose an EasyMining export.');}importConfigurationModal(b,f.name);}catch(err){toast(err.message,true);}});
}
function download(content,name,type){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function importConfigurationModal(input,filename){
  const backup=parseConfigurationBackup(input),s=backup.settings;
  const labels=Object.fromEntries([...amountFields,['mode','Execution mode'],['maxActive','Maximum concurrent packages'],['maxErrors','API error threshold'],['pollSeconds','Strategy interval · seconds'],['accountSyncSeconds','Account sync · seconds'],['autoSync','Automatic account sync'],['feeBufferBps','Price / fee reserve · basis points'],['timezone','Timezone'],['displayCurrency','Display currency'],['startHour','Buying window · from'],['endHour','Buying window · until']]);
  const moneyKeys=new Set(amountFields.map(([key])=>key));
  const summary=s?`<details><summary>Review software settings</summary><div class="import-summary">${Object.entries(s).filter(([key])=>!['running','liveArmed'].includes(key)).map(([key,value])=>key==='usdtLimits'?Object.entries(value).map(([k,v])=>`<div class="budget-row"><span>USDT · ${e(labels[k]||k)}</span><b>${exact(v)} USDT</b></div>`).join(''):`<div class="budget-row"><span>${e(labels[key]||key)}</span><b>${e(moneyKeys.has(key)?exact(value)+' BTC':typeof value==='boolean'?(value?'Enabled':'Disabled'):value)}</b></div>`).join('')}</div></details>`:'';
  openModal(modalHead('Import settings & strategies',e(filename))+`<p class="callout warning">Applying an import pauses the engine and disarms live buying. Imported strategies start paused. Review the restored limits and payout addresses before enabling them.${DEMO?' This preview keeps execution in paper mode.':''}</p><form id="import-form"><div class="field-grid"><div class="field full"><label class="check-field"><input type="checkbox" name="restoreSettings" ${s?'checked':'disabled'}>Restore software settings</label><small>${s?'Includes spending caps, schedules, timezone and automatic sync options.':'No software settings in this file.'}</small></div><div class="field full"><label class="check-field"><input type="checkbox" name="restoreStrategies" ${backup.strategies?'checked':'disabled'}>Restore strategies${backup.strategies?' · '+backup.strategies.length:''}</label></div>${backup.strategies?`<div class="field full"><label for="strategyMode">Strategy import method</label><select id="strategyMode" name="strategyMode"><option value="merge">Update matching strategies and add new ones</option><option value="replace">Replace current strategy list</option></select><small>Matching IDs keep their purchase history and latest buying interval. Replacing removes other strategy definitions; their ledger remains.</small></div>`:''}</div>${summary}${backup.strategies?`<details><summary>Review ${backup.strategies.length} paused strategies</summary><ul class="helper-list">${backup.strategies.map(x=>`<li><strong>${e(x.name)}</strong> · ${e(x.mode)} · ${e(x.coin)} · ceiling ${exact(x.maxPrice)} ${e(paymentMarket(x))} · ${x.continuous?'Continuous':'budget '+exact(x.budget)+' '+e(paymentMarket(x))}${x.payoutAddress?'<br>Reward address: '+e(x.payoutAddress):''}${x.mergePayoutAddress?'<br>Merged reward address: '+e(x.mergePayoutAddress):''}</li>`).join('')||'<li>No strategies. Replacing clears the current list.</li>'}</ul></details>`:''}<p class="import-note">Current purchase history, rewards, reconciliation records, API credentials and administrator login are retained. Ledger entries in an exported file are not imported.</p><div class="form-error" id="import-error"></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Apply import</button></div></form>`);
  $('#import-form').addEventListener('submit',async ev=>{
    ev.preventDefault();const button=ev.submitter;if(button.disabled)return;button.disabled=true;
    const f=new FormData(ev.target),options={restoreSettings:f.has('restoreSettings'),restoreStrategies:f.has('restoreStrategies'),strategyMode:f.get('strategyMode')||'merge'};
    try{await request('/api/import','POST',{backup,options});closeModal();await refresh();toast('Configuration restored. Engine paused; imported strategies are paused.');}
    catch(err){if($('#import-error'))$('#import-error').textContent=err.message;}
    finally{if(button.isConnected)button.disabled=false;}
  });
}
function exportCsv(){if(!DEMO){location.href='/api/export?format=csv&market='+ledgerMarket+'&mode='+state.settings.mode;return;}const rows=[['Package','Mode','Coin','Status','Purchased','Cost '+ledgerMarket,'Confirmed reward value '+ledgerMarket],...activeOrders().filter(isAccounted).map(o=>[o.name,o.mode,o.coin,o.status,o.createdAt,exact(o.costBtc),exact(totalRewards(o))])];const cell=v=>'"'+(/^[=+@-]/.test(String(v))?"'":'')+String(v).replaceAll('"','""')+'"';download(rows.map(r=>r.map(cell).join(',')).join('\r\n'),'easymining-paper-ledger.csv','text/csv');toast('Paper ledger exported');}
function exportDailyCsv(){
  if(!DEMO){location.href='/api/export?format=daily-csv&market='+ledgerMarket+'&mode='+state.settings.mode+'&days='+range;return;}
  const cell=v=>'"'+(/^[\s]*[=+@-]/.test(String(v))?"'":'')+String(v??'').replaceAll('"','""')+'"';
  download(dailyProfitCsvRows(dailyReport(),state.runtime.exchangeRates).map(r=>r.map(cell).join(',')).join('\r\n'),'easymining-daily-paper.csv','text/csv');toast('Daily paper report exported');
}
function passwordModal(){openModal(modalHead('Change administrator password')+`<form id="password-form"><div class="field-grid"><div class="field full">${field('current','Current password','',{type:'password'})}</div><div class="field full">${field('password','New password · at least 12 characters','',{type:'password'})}</div></div><div class="form-error" id="password-error"></div><div class="modal-actions"><button class="btn primary" type="submit">Save password</button></div></form>`);$('#password-form').addEventListener('submit',async ev=>{ev.preventDefault();try{await request('/api/password','POST',Object.fromEntries(new FormData(ev.target)));closeModal();toast('Password changed. Other sessions signed out.');}catch(err){$('#password-error').textContent=err.message;}});}
async function handleAction(name){
  if(name==='close-modal')return closeModal();
  if(name==='menu')return $('.sidebar')?.classList.toggle('open');
  if(name==='new-strategy')return strategyModal();
  if(name==='accounting')return accountingModal();
  if(name==='self-host'||name==='about')return selfHost();
  if(name==='arm')return armModal();
  if(name==='password')return passwordModal();
  if(name==='export-csv')return exportCsv();
  if(name==='export-daily')return exportDailyCsv();
  if(name==='debug-enable'||name==='debug-disable'){
    if(DEMO)return;
    return action('/api/debug','POST',{enabled:name==='debug-enable',minutes:Number($('#debug-duration')?.value||60)},name==='debug-enable'?'Purchase debug capture enabled. Engine settings are unchanged.':'Purchase debug capture stopped. Saved traces remain available.');
  }
  if(name==='debug-download'||name==='debug-view'){
    if(DEMO)return;
    try{
      const report=await request('/api/debug');
      if(name==='debug-download'){download(JSON.stringify(report,null,2),'easymining-purchase-debug.json','application/json');return;}
      openModal(modalHead('Purchase debug traces','Captured from normal evaluations and purchases.')+`<div class="field"><label for="debug-trace-select">Captured evaluation</label><select id="debug-trace-select">${debugTraceOptions(report.traces,state.settings.timezone)}</select></div><div id="debug-trace-content">${debugTraceView(report.traces[0],state.settings.timezone)}</div><div class="modal-actions"><button class="btn" data-action="debug-clear">Clear saved traces</button><button class="btn" data-action="debug-view">Refresh traces</button><button class="btn primary" data-action="debug-download">Download debug log</button></div>`);
      $('#debug-trace-select')?.addEventListener('change',ev=>{$('#debug-trace-content').innerHTML=debugTraceView(report.traces.find(t=>t.id===ev.target.value),state.settings.timezone);});
    }catch(error){toast(error.message,true);}
    return;
  }
  if(name==='debug-clear'){
    if(await action('/api/debug/traces','DELETE',{},'Saved debug traces cleared.'))closeModal();
    return;
  }
  if(name==='api-audit'){
    if(DEMO)return toast('The read-only account audit is available in the self-hosted Go server.');
    const button=document.querySelector('[data-action="api-audit"]');if(button)button.disabled=true;
    try{toast('Reading API responses; no purchase will be submitted.');const report=await request('/api/audit','POST',{});download(JSON.stringify(report,null,2),'easymining-api-audit.json','application/json');toast('Read-only API audit downloaded. No purchase was submitted.');}catch(error){toast(error.message,true);}finally{if(button)button.disabled=false;}
    return;
  }
  if(name==='purchase-diagnostics'){if(DEMO)download(JSON.stringify(purchaseDiagnostics(state,state.connection),null,2),'easymining-purchase-diagnostics.json','application/json');else location.href='/api/export?format=purchase-diagnostics';return;}
  if(name==='daily-older'){dailyPage++;return render();}
  if(name==='daily-newer'){dailyPage=Math.max(0,dailyPage-1);return render();}
  if(name==='refresh-rates')return action('/api/rates','POST',{},r=>r.error?'Rates unavailable; previous rates are retained.':'Display rates updated');
  if(name==='export-json'){if(DEMO){const s=structuredClone(state);s.version=VERSION;s.exportedAt=new Date().toISOString();s.settings.running=false;s.settings.liveArmed=false;delete s.connection;download(JSON.stringify(s,null,2),'easymining-backup.json','application/json');return;}location.href='/api/export';return;}
  if(name==='export-settings'){if(DEMO)download(JSON.stringify(configurationBackup(state),null,2),'easymining-settings.json','application/json');else location.href='/api/export?format=settings';return;}
  if(name==='import-settings')return $('#import-file')?.click();
  if(name==='reset-demo'){openModal(modalHead('Reset the paper workspace?')+'<p class="callout">Your browser’s demo strategies, settings and simulated purchases will be replaced by the original sample.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn danger" id="reset-confirm">Reset demo</button></div>');$('#reset-confirm').addEventListener('click',async()=>{if(await action('/api/reset-demo','POST',{},'Demo reset'))closeModal();});return;}
  if(name==='toggle-engine'){
    if(state.settings.running)return action('/api/pause','POST',{},'Engine paused. An in-flight request may still complete.');
    if(state.settings.mode==='live'&&!state.settings.liveArmed)return armModal();
    return action('/api/settings','POST',{running:true},'Engine started');
  }
  if(name==='telegram-test')return action('/api/telegram/test','POST',{},'Telegram test delivered');
  if(name==='telegram-report'){try{const r=await request('/api/telegram/report','POST',{});await refresh();toast(r.message||'Daily report queued');}catch(error){toast(error.message,true);}return;}
  if(name==='telegram-remove')return action('/api/telegram','POST',{clear:true},'Telegram connection removed');
  if(name==='telegram-preview'){try{const r=await request('/api/telegram/report');openModal(modalHead('Daily Telegram report',e(r.date)+' · '+e(r.timezone))+`<p class="callout">${DEMO?'Illustrative paper data only.':'Preview of the previous calendar day’s live ledger. Viewing this does not send a message.'}</p><pre class="telegram-report-preview">${e(r.text)}</pre><div class="modal-actions"><button class="btn primary" data-action="close-modal">Done</button></div>`);}catch(error){toast(error.message,true);}return;}
  if(name==='evaluate')return action('/api/tick','POST',{},'Evaluation completed. See the activity log for each decision.');
  if(name==='sync'||name==='refresh-catalogue'){toast('Synchronizing with NiceHash…');return action('/api/sync','POST',{},result=>result.buyingReady&&result.historyComplete===false?'Spending verified. Other teams may continue while order details refresh.':result.historyComplete===false?'History is still updating. Automatic account sync will retry.':'Account history verified and synced');}
  if(name==='use-server-connection')return action('/api/connection/server','POST',{},'Server NiceHash configuration selected. Test & sync to verify.');
  if(name==='disconnect')return action('/api/connection','DELETE',{},'Account disconnected. Engine paused.');
  if(name==='logout'){await request('/api/auth/logout','POST',{});state=null;return auth(false);}
}
document.addEventListener('click',async ev=>{
  const target=ev.target.closest('[data-action],[data-page],[data-toggle],[data-edit],[data-follow-team],[data-chart],[data-order],[data-package],[data-buy-package],[data-package-filter],[data-history-filter],[data-day],[data-value-reward],[data-confirm-reward]');
  if(!target)return;ev.preventDefault();
  if(target.dataset.page){location.hash=target.dataset.page;if(location.hash.slice(1)===page)render();return;}
  if(target.dataset.action){if(target.disabled)return;target.disabled=true;try{await handleAction(target.dataset.action);}catch(err){toast(err.message,true);}finally{if(target.isConnected)target.disabled=false;}return;}
  if(target.dataset.toggle){const s=state.strategies.find(s=>s.id===target.dataset.toggle);await action('/api/strategies','POST',{...s,enabled:!s.enabled},s.enabled?'Strategy paused':'Strategy enabled');return;}
  if(target.dataset.edit)return strategyModal(target.dataset.edit);
  if(target.dataset.followTeam){const s=state.strategies.find(s=>s.id===target.dataset.followTeam);if(s)return action('/api/strategies','POST',{...s,packageId:''},'Strategy now follows current matching team lobbies');return;}
  if(target.dataset.chart){chartMetric=target.dataset.chart;return render();}
  if(target.dataset.order){const order=state.orders.find(o=>o.id===target.dataset.order);if(order&&paymentMarket(order)!==ledgerMarket){ledgerMarket=paymentMarket(order);render();}return orderModal(target.dataset.order);}
  if(target.dataset.buyPackage)return purchaseModal(target.dataset.buyPackage);
  if(target.dataset.package){const p=state.packages.find(p=>p.id===target.dataset.package);return strategyModal(null,{name:p.name+' · new strategy',market:paymentMarket(p),continuous:true,mode:p.team?'team':'solo',kind:p.team?'team':'interval',coin:p.coin,packageName:p.name,maxPrice:money(p,'costBtc'),budget:Math.max(money(p,'costBtc')*10,units('0.001')),maxPurchases:10});}
  if(target.dataset.packageFilter){packageFilter=target.dataset.packageFilter;return render();}
  if(target.dataset.historyFilter){historyFilter=target.dataset.historyFilter;return render();}
  if(target.dataset.day!==undefined){target.classList.toggle('selected');target.setAttribute('aria-pressed',target.classList.contains('selected'));return;}
  if(target.dataset.confirmReward)return confirmRewardModal(target.dataset.confirmReward);
  if(target.dataset.valueReward){openModal(modalHead('Add a '+ledgerMarket+' reward valuation','This updates the report value, not the reward confirmation status.')+`<form id="value-form"><div class="field-grid"><div class="field full">${field('valueBtc',ledgerMarket+' equivalent','',{type:'number',min:0,step:'0.00000001'})}</div><div class="field full">${field('note','Valuation source and date','')}</div></div><div class="form-error" id="value-error"></div><div class="modal-actions"><button class="btn primary" type="submit">Save valuation</button></div></form>`);$('#value-form').addEventListener('submit',async ev=>{ev.preventDefault();try{const b=Object.fromEntries(new FormData(ev.target));b.valueBtc=units(b.valueBtc);if(ledgerMarket==='USDT'){b.valueUsdt=b.valueBtc;delete b.valueBtc;}await request('/api/reward-value','POST',{...b,currency:ledgerMarket,id:target.dataset.valueReward});closeModal();await refresh();toast('Reward valuation saved');}catch(err){$('#value-error').textContent=err.message;}});}
});
document.addEventListener('keydown',ev=>{const m=$('.modal');if(!m)return;if(ev.key==='Escape')closeModal();if(ev.key==='Tab'){const list=[...m.querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled&&x.type!=='hidden');const first=list[0],last=list.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
document.addEventListener('pointermove',ev=>{const rect=ev.target.closest('[data-tip]'),tip=$('#chart-tooltip');if(!tip)return;if(rect){tip.textContent=rect.dataset.tip;tip.style.display='block';const box=$('.chart-wrap').getBoundingClientRect();tip.style.left=Math.max(4,Math.min(box.width-210,ev.clientX-box.left-75))+'px';}else tip.style.display='none';});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';closeModal();render();window.scrollTo(0,0);});
async function auth(setup){$('#app').innerHTML=`<div class="auth-screen"><div class="auth-story"><a href="/" class="brand"><span class="logo-mark">F<span>↗</span></span><span class="brand-name">FastPool<small>EASYMINING</small></span></a><div><div class="overline">THE MINING DESK</div><h1>Your strategy.<br>Your limits.<br><span>Your control.</span></h1><p>Thoughtful package buying. A transparent ledger. Every setting in one place.</p></div><small style="font-size:10px;color:#839477">Independent software · NiceHash EasyMining</small></div><div class="auth-form"><form id="auth-form"><div class="overline">PRIVATE WORKSPACE</div><h2>${setup?'Set up your mining desk.':'Welcome back.'}</h2><p>${setup?'Use the one-time token from your server console to create your administrator account.':'Sign in to manage your strategies and check your results.'}</p><div class="field-grid">${setup?'<div class="field full">'+field('token','One-time setup token','',{type:'password'})+'</div>':''}<div class="field full">${field('login-password',setup?'Create password · at least 12 characters':'Administrator password','',{type:'password'})}</div></div><div class="form-error" id="auth-error"></div><button class="btn primary" type="submit">${setup?'Create workspace':'Sign in'} ${icon('arrow')}</button></form></div></div>`;$('#auth-form').addEventListener('submit',async ev=>{ev.preventDefault();const b={password:$('#login-password').value,...(setup?{token:$('#token').value}:{})};try{const r=await fetch(setup?'/api/auth/setup':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),d=await r.json();if(!r.ok)throw new Error(d.error);await refresh();}catch(err){$('#auth-error').textContent=err.message;}});}
async function boot(){try{if(DEMO){api=await DemoApi.open();await refresh();}else{const r=await fetch('/api/auth/status'),a=await r.json();if(a.authenticated)await refresh();else auth(a.setup);}}catch(err){$('#app').innerHTML='<div class="loading"><p>Could not open the workspace.</p><p>'+e(err.message)+'</p><button class="btn" id="retry">Try again</button></div>';$('#retry').addEventListener('click',()=>location.reload());}}
await boot();
function updateLiveStatus(){
  const presentation=syncPresentation(state);
  document.querySelectorAll('[data-engine-label]').forEach(el=>el.textContent=presentation.engine);
  document.querySelectorAll('[data-live-armed]').forEach(el=>el.textContent=state.settings.liveArmed?'Armed':'Disarmed');
  document.querySelectorAll('[data-connection-status]').forEach(el=>el.textContent=DEMO?'Demo · no NiceHash account connected':presentation.connectionText);
  document.querySelectorAll('[data-sync-warnings]').forEach(el=>el.innerHTML=warningContent());
  document.querySelectorAll('[data-account-sync-status]').forEach(el=>{if(!DEMO)el.textContent=state.settings.autoSync!==false?'Automatic account sync is enabled · every '+(state.settings.accountSyncSeconds||60)+' seconds, including while the engine is paused.':'Automatic account sync is disabled.';});
  document.querySelectorAll('[data-action="toggle-engine"]').forEach(el=>{const label=state.settings.running?'Pause engine':'Start engine';el.setAttribute('aria-label',label);el.innerHTML=icon(state.settings.running?'pause':'play')+(el.classList.contains('icon-btn')?'':label);});
}
setInterval(async()=>{
  if(!state)return;
  try{state=await request('/api/state');if($('.modal')||['settings','strategies','marketplace'].includes(page)||document.activeElement?.matches('input,select,textarea'))updateLiveStatus();else render();}catch{}
},10000);
if(DEMO)setInterval(async()=>{if(state?.settings.running){try{await api.request('/api/tick','POST',{});if(!$('.modal')&&page==='overview')await refresh();}catch{}}},60000);
